INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('increase-1', 'increase', 'There was a steady increase in the number of tourists after 2010.', '2010 年后,游客数量稳步增加。', 'increase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('increase-2', 'increase', 'Spending on healthcare increased by ten percent between 2000 and 2010.', '2000 年至 2010 年间,医疗支出增加了百分之十。', 'increased');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decrease-1', 'decrease', 'The chart shows a decrease in the use of coal over the period.', '图表显示,在此期间煤炭使用量有所减少。', 'decrease');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decrease-2', 'decrease', 'The number of cinema visits decreased slightly during the following decade.', '在随后的十年里,观影人次略有减少。', 'decreased');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rise-1', 'rise', 'There was a sharp rise in house prices between 2005 and 2007.', '2005 年至 2007 年间,房价急剧上升。', 'rise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rise-2', 'rise', 'Sales are expected to rise gradually over the next five years.', '预计未来五年销售额将逐步上升。', 'rise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fall-1', 'fall', 'There was a sharp fall in car sales between 2010 and 2015.', '2010 年至 2015 年间,汽车销量急剧下降。', 'fall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fall-2', 'fall', 'The proportion of households with a landline fell steadily over the period.', '在此期间,拥有固定电话的家庭比例持续下降。', 'fell');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decline-1', 'decline', 'The chart shows a gradual decline in newspaper sales since 2000.', '图表显示,自 2000 年以来报纸销量逐渐下降。', 'decline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decline-2', 'decline', 'The number of farmers declined rapidly throughout the second half of the century.', '在二十世纪下半叶,农民数量迅速下降。', 'declined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drop-1', 'drop', 'There was a significant drop in the number of students in 2012.', '2012 年学生人数大幅下降。', 'drop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drop-2', 'drop', 'Oil consumption dropped to its lowest level at the end of the period.', '在这一时期末,石油消费量下降到最低水平。', 'dropped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('climb-1', 'climb', 'The figure continued to climb, reaching a peak of eighty percent in 2015.', '这一数字持续攀升,在 2015 年达到百分之八十的峰值。', 'climb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soar-1', 'soar', 'The number of internet users soared from one million to ten million.', '互联网用户数量从一百万猛增到一千万。', 'soared');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surge-1', 'surge', 'There was a surge in demand for electric cars after 2020.', '2020 年后,电动汽车的需求激增。', 'surge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rocket-1', 'rocket', 'The price of petrol rocketed in the first half of the year.', '汽油价格在上半年飞涨。', 'rocketed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plummet-1', 'plummet', 'The value of exports plummeted from 50 million to 10 million dollars.', '出口额从五千万美元暴跌到一千万美元。', 'plummeted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plunge-1', 'plunge', 'The temperature plunges to below zero in the winter months.', '冬季气温骤降到零度以下。', 'plunges');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dip-1', 'dip', 'After a slight dip in 2008, the figures began to rise again.', '2008 年略有下降之后,这些数字又开始上升。', 'dip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dip-2', 'dip', 'Sales dipped slightly in March before recovering in the following month.', '销售额在三月小幅下降,随后在下个月回升。', 'dipped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slump-1', 'slump', 'The housing market experienced a slump at the beginning of the 1990s.', '20 世纪 90 年代初,住房市场经历了暴跌。', 'slump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fluctuate-1', 'fluctuate', 'The price of wheat continued to fluctuate throughout the ten-year period.', '在这十年间,小麦价格持续波动。', 'fluctuate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fluctuation-1', 'fluctuation', 'There were minor fluctuations in the rate of unemployment during this time.', '在此期间,失业率有小幅波动。', 'fluctuations');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stabilise-1', 'stabilise', 'The number of visitors began to stabilise at around two million in 2018.', '2018 年,游客数量开始稳定在两百万左右。', 'stabilise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('level-off-1', 'level-off', 'Car ownership rose quickly and then began to level off after 2010.', '汽车拥有量迅速上升,2010 年后开始趋于平稳。', 'level off');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plateau-1', 'plateau', 'Sales reached a plateau in 2015 and stayed unchanged for three years.', '销售额在 2015 年进入平稳期,此后三年保持不变。', 'plateau');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plateau-2', 'plateau', 'Most of the country''s people live on a high plateau in the centre.', '该国大部分人口居住在中部的高原上。', 'plateau');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peak-1', 'peak', 'The number of students reached a peak of 5,000 in 2012.', '学生人数在 2012 年达到 5000 人的顶峰。', 'peak');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peak-2', 'peak', 'Electricity use peaked at around seven o''clock in the evening.', '用电量在晚上七点左右达到峰值。', 'peaked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bottom-out-1', 'bottom-out', 'The figures appeared to bottom out in 2009 and then slowly recovered.', '这些数字似乎在 2009 年触底,然后缓慢回升。', 'bottom out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remain-stable-1', 'remain-stable', 'The proportion of older workers is expected to remain stable until 2030.', '预计到 2030 年,老年工人的比例将保持稳定。', 'remain stable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('steady-1', 'steady', 'The graph shows a steady rise in the use of public transport.', '图表显示,公共交通的使用量平稳上升。', 'steady');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gradual-1', 'gradual', 'There was a gradual increase in the average age of the population.', '人口平均年龄逐渐上升。', 'gradual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moderate-1', 'moderate', 'The middle group showed only a moderate change over the twenty years.', '中间组在这二十年里只出现了适度的变化。', 'moderate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slight-1', 'slight', 'There was a slight decrease in the number of people using buses.', '乘坐公交车的人数略有减少。', 'slight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marginal-1', 'marginal', 'The difference between the two figures in 2005 was only marginal.', '2005 年这两个数字之间的差异很小。', 'marginal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('considerable-1', 'considerable', 'A considerable number of graduates went on to work overseas.', '相当多的毕业生后来去了海外工作。', 'considerable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('substantial-1', 'substantial', 'The chart shows a substantial increase in spending on online advertising.', '图表显示,网络广告支出大幅增长。', 'substantial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('significant-1', 'significant', 'There was a significant difference between the salaries of men and women.', '男女工资之间存在显著差异。', 'significant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dramatic-1', 'dramatic', 'The use of mobile phones saw a dramatic rise during the 1990s.', '20 世纪 90 年代,手机使用量剧烈上升。', 'dramatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sharp-1', 'sharp', 'The table shows a sharp fall in the birth rate after 1960.', '表格显示,1960 年后出生率急剧下降。', 'sharp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('steep-1', 'steep', 'There was a steep rise in the number of cars during the 1980s.', '20 世纪 80 年代,汽车数量急剧上升。', 'steep');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rapid-1', 'rapid', 'The rapid growth of cities has led to a shortage of housing.', '城市的迅速发展导致了住房短缺。', 'rapid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exponential-1', 'exponential', 'The number of smartphone users showed exponential growth after 2008.', '2008 年后,智能手机用户数量呈指数级增长。', 'exponential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overall-1', 'overall', 'Overall, the proportion of people living in cities increased over the period.', '总体而言,在此期间城市人口比例有所上升。', 'Overall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trend-1', 'trend', 'The overall trend shows that fewer people are buying printed books.', '总体趋势显示,购买纸质书的人越来越少。', 'trend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pattern-1', 'pattern', 'A similar pattern can be seen in the figures for the other two countries.', '另外两个国家的数字也呈现类似的模式。', 'pattern');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proportion-1', 'proportion', 'The proportion of women in the workforce rose from 30 to 45 percent.', '劳动力中女性的比例从百分之三十上升到百分之四十五。', 'proportion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('percentage-1', 'percentage', 'The percentage of households with a computer doubled in only five years.', '拥有电脑的家庭百分比在短短五年内翻了一番。', 'percentage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ratio-1', 'ratio', 'The ratio of teachers to students was highest in the smaller schools.', '较小学校的师生比最高。', 'ratio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rate-1', 'rate', 'The unemployment rate remained below five percent for most of the decade.', '这十年的大部分时间里,失业率保持在百分之五以下。', 'rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fraction-1', 'fraction', 'Only a small fraction of the waste was recycled in the first year.', '第一年只有一小部分废物被回收。', 'fraction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('majority-1', 'majority', 'The majority of students preferred to live in shared flats.', '大多数学生更愿意住在合租公寓里。', 'majority');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minority-1', 'minority', 'Only a small minority of people cycled to work in 2010.', '2010 年,只有少数人骑车上班。', 'minority');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quarter-1', 'quarter', 'Almost a quarter of the budget was spent on education.', '近四分之一的预算用于教育。', 'quarter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quarter-2', 'quarter', 'Profits rose in the final quarter of the year after a difficult start.', '经历了艰难的开局后,利润在第四季度有所上升。', 'quarter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('double-1', 'double', 'The number of overseas students doubled between 2000 and 2010.', '2000 年至 2010 年间,海外学生人数翻了一番。', 'doubled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('triple-1', 'triple', 'The population of the city tripled in less than thirty years.', '这座城市的人口在不到三十年内增至三倍。', 'tripled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('halve-1', 'halve', 'The number of smokers halved during the period shown on the graph.', '在图表所示时期内,吸烟人数减少了一半。', 'halved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('average-1', 'average', 'The average for the whole country was about twelve percent.', '全国的平均数约为百分之十二。', 'average');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('average-2', 'average', 'The average price of a house rose by a third in ten years.', '十年间,平均房价上涨了三分之一。', 'average');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mean-1', 'mean', 'The mean of the five results was thirty-two points.', '这五个结果的平均值是三十二分。', 'mean');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('median-1', 'median', 'The median age of the population was thirty-five in 2010.', '2010 年,人口年龄的中位数是三十五岁。', 'median');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('range-1', 'range', 'The prices cover a wide range, from two pounds to more than fifty.', '价格范围很广,从两英镑到五十多英镑不等。', 'range');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('range-2', 'range', 'Ages in the group range from eighteen to sixty-five years old.', '这个群体的年龄在十八岁到六十五岁之间。', 'range');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('total-1', 'total', 'Coal accounted for one third of the total energy used in that year.', '煤炭占当年能源使用总量的三分之一。', 'total');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('total-2', 'total', 'The company employed a total of 500 people in the three factories.', '这家公司在三家工厂共雇用了 500 人。', 'total');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aggregate-1', 'aggregate', 'The aggregate for the three years was just under two million.', '这三年的总计略低于两百万。', 'aggregate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sum-1', 'sum', 'The sum spent on advertising rose sharply in the final year.', '最后一年的广告支出总额急剧上升。', 'sum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('figure-1', 'figure', 'The figure for France was twice as high as that for Spain.', '法国的数字是西班牙的两倍。', 'figure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('figure-2', 'figure', 'Einstein is a key figure in the history of modern science.', '爱因斯坦是现代科学史上的关键人物。', 'figure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amount-1', 'amount', 'The amount of waste produced by each household fell over the period.', '在此期间,每户家庭产生的垃圾量有所减少。', 'amount');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quantity-1', 'quantity', 'The quantity of goods moved by rail remained the same.', '铁路运输的货物数量保持不变。', 'quantity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capacity-1', 'capacity', 'The new power station has twice the capacity of the old one.', '新发电站的容量是旧发电站的两倍。', 'capacity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('margin-1', 'margin', 'The Green Party won by a narrow margin in the 2015 election.', '绿党在 2015 年选举中以微弱差额获胜。', 'margin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gap-1', 'gap', 'The gap between the rich and the poor widened during the decade.', '这十年间,贫富差距扩大了。', 'gap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discrepancy-1', 'discrepancy', 'There is a large discrepancy between the figures for the two regions.', '这两个地区的数字之间存在很大差异。', 'discrepancy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disparity-1', 'disparity', 'The table reveals a great disparity in income between men and women.', '表格显示男女收入存在巨大悬殊。', 'disparity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equivalent-1', 'equivalent', 'Spending on food was equivalent to a third of average income.', '食品支出相当于平均收入的三分之一。', 'equivalent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comparable-1', 'comparable', 'The figures for the two countries were comparable throughout the period.', '这两个国家的数字在整个时期都是可比的。', 'comparable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('respectively-1', 'respectively', 'Sales in Japan and Korea rose by ten and fifteen percent respectively.', '日本和韩国的销售额分别增长了百分之十和百分之十五。', 'respectively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approximately-1', 'approximately', 'Approximately half of the people surveyed said they exercised regularly.', '大约一半的受访者表示他们经常锻炼。', 'Approximately');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('roughly-1', 'roughly', 'Roughly a third of the students came from other countries.', '大致三分之一的学生来自其他国家。', 'Roughly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nearly-1', 'nearly', 'Nearly seventy percent of households owned a car in 2010.', '2010 年,近百分之七十的家庭拥有汽车。', 'Nearly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exceed-1', 'exceed', 'The number of electric cars is expected to exceed that of diesel cars.', '预计电动汽车的数量将超过柴油车。', 'exceed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surpass-1', 'surpass', 'Sales of online books may surpass those of printed ones by 2030.', '到 2030 年,电子书销量可能超越纸质书。', 'surpass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overtake-1', 'overtake', 'Spain overtook Italy as the most popular destination in 2012.', '2012 年,西班牙超过意大利,成为最受欢迎的目的地。', 'overtook');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outnumber-1', 'outnumber', 'Women outnumber men in most university courses in this country.', '在这个国家的大多数大学课程中,女性人数超过男性。', 'outnumber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constitute-1', 'constitute', 'Older people constitute about a quarter of the total population.', '老年人约占总人口的四分之一。', 'constitute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comprise-1', 'comprise', 'The group comprises twenty teachers from six different schools.', '这个小组包含来自六所不同学校的二十名教师。', 'comprises');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consist-of-1', 'consist-of', 'The process consists of five main stages, beginning with the collection of materials.', '这个过程由五个主要阶段组成,首先是收集材料。', 'consists of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('represent-1', 'represent', 'Students represent the largest group of people using the library.', '学生占图书馆使用者的最大比例。', 'represent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('occupy-1', 'occupy', 'Farmland occupies the largest area of the town on both maps.', '在两张地图上,农田都占据了该镇最大的面积。', 'occupies');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distribution-1', 'distribution', 'The chart shows the distribution of wealth across the five regions.', '图表显示了财富在五个地区的分布。', 'distribution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('allocate-1', 'allocate', 'The government chose to allocate more money to health than to defence.', '政府选择把更多资金分配给医疗,而不是国防。', 'allocate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('projection-1', 'projection', 'According to projections, the population will reach ten million by 2050.', '据预测,到 2050 年人口将达到一千万。', 'projections');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('period-1', 'period', 'Sales rose steadily over the period from 2000 to 2010.', '2000 年到 2010 年期间,销售额稳步上升。', 'period');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decade-1', 'decade', 'The number of cyclists increased steadily during the following decade.', '在接下来的十年里,骑自行车的人数持续增加。', 'decade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('century-1', 'century', 'The city''s population grew rapidly in the early part of the century.', '这座城市的人口在本世纪初迅速增长。', 'century');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interval-1', 'interval', 'Measurements were taken at regular intervals throughout the day.', '全天每隔一定时间进行一次测量。', 'intervals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('annual-1', 'annual', 'Annual sales rose from two million to five million over the period.', '在此期间,年销售额从两百万增长到五百万。', 'Annual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('per-capita-1', 'per-capita', 'Water use per capita was highest in the United States.', '美国的人均用水量最高。', 'per capita');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enormous-1', 'enormous', 'There was an enormous difference between the two countries in 1990.', '1990 年,这两个国家之间存在巨大差异。', 'enormous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tremendous-1', 'tremendous', 'The new technology has had a tremendous effect on the way we shop.', '新技术对我们的购物方式产生了巨大影响。', 'tremendous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abundant-1', 'abundant', 'The country has abundant natural resources but poor transport links.', '这个国家自然资源丰富,但交通不便。', 'abundant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abundance-1', 'abundance', 'Developed countries enjoy an abundance of cheap food all year round.', '发达国家全年都有丰富的廉价食品。', 'abundance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bulk-1', 'bulk', 'The bulk of the country''s energy came from coal in 1990.', '1990 年,该国的大部分能源来自煤炭。', 'bulk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rank-1', 'rank', 'Germany ranked first in terms of the number of cars produced.', '就汽车产量而言,德国排名第一。', 'ranked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('onwards-1', 'onwards', 'From 2010 onwards, the number of cyclists increased every single year.', '从 2010 年起,骑自行车的人数逐年增加。', 'onwards');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mid-1', 'mid', 'Sales began to fall in the mid-1990s and never fully recovered.', '销售额从 20 世纪 90 年代中期开始下降,一直没有完全恢复。', 'mid-1990s');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bracket-1', 'bracket', 'People in the 25 to 34 age bracket spent the most on travel.', '25 至 34 岁年龄段的人旅游支出最多。', 'bracket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('axis-1', 'axis', 'The vertical axis shows the number of people, measured in thousands.', '纵轴显示人数,单位为千。', 'axis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slash-1', 'slash', 'The company had to slash its advertising budget during the crisis.', '危机期间,这家公司不得不大幅削减广告预算。', 'slash');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('upward-1', 'upward', 'The graph shows a clear upward trend in the use of renewable energy.', '图表显示可再生能源的使用量呈明显的上升趋势。', 'upward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('millimetre-1', 'millimetre', 'Average rainfall reached 200 millimetres in the wettest month.', '最潮湿的月份平均降雨量达到 200 毫米。', 'millimetres');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('width-1', 'width', 'The width of the road increased from two lanes to four.', '道路的宽度从两车道增加到四车道。', 'width');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depth-1', 'depth', 'Water is pumped up from a depth of about thirty metres.', '水从约三十米的深度被抽上来。', 'depth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curve-1', 'curve', 'The curve for France rises much more steeply than the others.', '法国的曲线比其他国家上升得陡峭得多。', 'curve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slide-1', 'slide', 'The company''s share of the market continued to slide in 2015.', '2015 年,这家公司的市场份额继续下滑。', 'slide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weekly-1', 'weekly', 'The chart shows the average weekly spending of students on food.', '图表显示了学生每周在食品上的平均支出。', 'weekly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cumulative-1', 'cumulative', 'The cumulative effect of small changes may be very large.', '小变化的累积效应可能非常大。', 'cumulative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('census-1', 'census', 'According to the last census, the city had about two million inhabitants.', '根据最近一次人口普查,这座城市约有两百万居民。', 'census');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stage-1', 'stage', 'At the first stage of the process, the fruit is washed and sorted.', '在这一过程的第一阶段,水果被清洗和分拣。', 'stage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phase-1', 'phase', 'In the final phase, the finished products are sent to the shops.', '在最后阶段,成品被送往商店。', 'phase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('step-1', 'step', 'The next step involves heating the mixture to a high temperature.', '下一步是把混合物加热到高温。', 'step');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sequence-1', 'sequence', 'The diagram shows the sequence of events in the making of paper.', '该图显示了造纸过程的先后顺序。', 'sequence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cycle-1', 'cycle', 'The diagram illustrates the life cycle of a salmon from egg to adult.', '该图展示了鲑鱼从卵到成鱼的生命循环。', 'cycle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('input-1', 'input', 'The main input of the process is fresh water from the river.', '这一过程的主要投入是河里的淡水。', 'input');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('output-1', 'output', 'The factory''s output doubled after the new machines were installed.', '安装新机器后,工厂的产出翻了一番。', 'output');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raw-material-1', 'raw-material', 'Sand, the main raw material, is delivered to the factory by truck.', '主要原材料沙子由卡车运送到工厂。', 'raw material');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extract-1', 'extract', 'The oil is extracted from the seeds using a large machine.', '用大型机器从种子中提取油。', 'extracted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refine-1', 'refine', 'The sugar is then refined to produce a fine white powder.', '然后把糖提炼成细白粉末。', 'refined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('filter-1', 'filter', 'The water is filtered to remove any dirt before it is stored.', '水在储存前先过滤,以去除污垢。', 'filtered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('filter-2', 'filter', 'The dirty water passes through a filter made of sand and stones.', '脏水通过由沙子和石头制成的过滤器。', 'filter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heat-1', 'heat', 'The mixture is heated to about 100 degrees and left for one hour.', '混合物被加热到约 100 度,然后放置一小时。', 'heated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cool-1', 'cool', 'The glass is then cooled slowly to prevent it from breaking.', '然后把玻璃慢慢冷却,防止破裂。', 'cooled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dissolve-1', 'dissolve', 'The salt is dissolved in warm water before being added to the tank.', '盐先溶解在温水中,然后加入水箱。', 'dissolved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mix-1', 'mix', 'The sand is mixed with water and small stones to form concrete.', '沙子与水和小石子混合,形成混凝土。', 'mixed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grind-1', 'grind', 'The beans are ground into a fine powder by a large machine.', '咖啡豆被大型机器研磨成细粉。', 'ground');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crush-1', 'crush', 'The rocks are crushed into small pieces before being transported.', '岩石先被压碎成小块,然后运走。', 'crushed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compress-1', 'compress', 'The waste paper is compressed into large blocks at the recycling centre.', '废纸在回收中心被压缩成大块。', 'compressed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pump-1', 'pump', 'Water is pumped from the river to a large tank on the hill.', '水从河里被抽送到山上的大水箱。', 'pumped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pump-2', 'pump', 'A small electric pump moves the water through the pipes.', '一台小型电泵把水输送到管道中。', 'pump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transport-1', 'transport', 'The bottles are transported by lorry to the supermarkets.', '瓶子由卡车运输到超市。', 'transported');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('package-1', 'package', 'Once dried, the tea leaves are packaged and transported to shops.', '茶叶干燥后被包装并运往商店。', 'packaged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dispatch-1', 'dispatch', 'The finished goods are dispatched to customers within two working days.', '成品在两个工作日内发送给顾客。', 'dispatched');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convert-1', 'convert', 'The solar panels convert sunlight into electricity for the building.', '太阳能电池板把阳光转换成电力,供建筑使用。', 'convert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transform-1', 'transform', 'Heat from the sun transforms the water into vapour, which rises into the air.', '太阳的热量把水转化为水蒸气,升入空气中。', 'transforms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recycle-1', 'recycle', 'Glass bottles can be recycled again and again without any loss of quality.', '玻璃瓶可以反复回收利用,质量不会受损。', 'recycled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('construct-1', 'construct', 'A new bridge was constructed across the river between the two maps.', '在两张地图所示时间之间,河上建造了一座新桥。', 'constructed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('demolish-1', 'demolish', 'The old houses were demolished to make way for a shopping centre.', '老房子被拆除,为购物中心腾出地方。', 'demolished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('replace-1', 'replace', 'The car park was replaced by a small garden and a playground.', '停车场被一个小花园和一个游乐场取代。', 'replaced');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relocate-1', 'relocate', 'The school was relocated to the north of the town in 2005.', '这所学校于 2005 年迁到了镇子北部。', 'relocated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expand-1', 'expand', 'The airport was expanded to include a second terminal and a new runway.', '机场进行了扩建,增加了第二座航站楼和一条新跑道。', 'expanded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extend-1', 'extend', 'The railway line was extended to the east of the town.', '铁路线延伸到了镇子东部。', 'extended');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convert-a-into-b-1', 'convert-a-into-b', 'The old warehouses were converted into flats during the 1990s.', '20 世纪 90 年代,这些旧仓库被改造成公寓。', 'converted into');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('redevelop-1', 'redevelop', 'The area around the port was redeveloped with shops and restaurants.', '港口周边地区被重新开发,建起了商店和餐馆。', 'redeveloped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('renovate-1', 'renovate', 'The old museum was renovated and now has a much larger entrance.', '老博物馆翻新后,现在有了大得多的入口。', 'renovated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pedestrianise-1', 'pedestrianise', 'The main street was pedestrianised, and cars are no longer allowed.', '主街被改为步行区,不再允许汽车通行。', 'pedestrianised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insert-1', 'insert', 'The sheets of paper are inserted into the machine one at a time.', '纸张被一张一张地插入机器。', 'inserted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flip-1', 'flip', 'The bricks are flipped over halfway through the drying process.', '砖块在干燥过程进行到一半时被翻转。', 'flipped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blend-1', 'blend', 'The fruit is blended with sugar and water to produce juice.', '水果与糖和水混合,制成果汁。', 'blended');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chop-1', 'chop', 'The vegetables are chopped into small pieces and then cooked.', '蔬菜被切碎,然后烹煮。', 'chopped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trim-1', 'trim', 'The edges of the paper are trimmed before the book is bound.', '书籍装订前,要修剪纸张的边缘。', 'trimmed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soak-1', 'soak', 'The seeds are soaked in water overnight to make them softer.', '种子在水中浸泡一夜,使其变软。', 'soaked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flush-1', 'flush', 'The pipes are flushed with clean water to remove any remaining chemicals.', '用清水冲洗管道,以去除残留的化学物质。', 'flushed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drill-1', 'drill', 'Workers drill a deep hole to reach the water under the ground.', '工人钻一个深孔,以取得地下水。', 'drill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('load-1', 'load', 'The finished bricks are loaded onto trucks and delivered to customers.', '成品砖被装上卡车,送到顾客手中。', 'loaded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carry-out-1', 'carry-out', 'Scientists carry out regular tests to check the quality of the water.', '科学家定期开展测试,检查水质。', 'carry out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('set-up-1', 'set-up', 'The government should set up more training centres for young people.', '政府应该为年轻人设立更多培训中心。', 'set up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bring-about-1', 'bring-about', 'New technology can bring about great changes in the way we work.', '新技术可以给我们的工作方式带来巨大变化。', 'bring about');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-into-account-1', 'take-into-account', 'Governments should take into account the needs of older people when planning transport.', '政府在规划交通时应考虑老年人的需求。', 'take into account');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-into-consideration-1', 'take-into-consideration', 'Employers should take into consideration the experience of each candidate.', '雇主应考虑每位候选人的经验。', 'take into consideration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-measures-1', 'take-measures', 'Governments must take measures to reduce the level of air pollution.', '政府必须采取措施降低空气污染水平。', 'take measures');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-responsibility-for-1', 'take-responsibility-for', 'Parents should take responsibility for teaching their children good manners.', '父母应该负责教孩子良好的礼貌。', 'take responsibility for');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-advantage-of-1', 'take-advantage-of', 'Students should take advantage of the opportunities offered by the internet.', '学生应该利用互联网提供的机会。', 'take advantage of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('make-use-of-1', 'make-use-of', 'Cities should make use of empty buildings instead of building on farmland.', '城市应该利用空置的建筑,而不是在农田上建房。', 'make use of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('make-up-1', 'make-up', 'Women make up nearly half of the workforce in many developed countries.', '在许多发达国家,女性占劳动力的近一半。', 'make up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('play-a-role-in-1', 'play-a-role-in', 'Parents play a role in shaping their children''s attitudes towards education.', '父母在塑造孩子对教育的态度方面起着作用。', 'play a role in');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('have-an-impact-on-1', 'have-an-impact-on', 'Fast food can have an impact on the health of young people.', '快餐可能对年轻人的健康产生影响。', 'have an impact on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('have-access-to-1', 'have-access-to', 'All children should have access to free and good quality education.', '所有孩子都应该能接受免费的优质教育。', 'have access to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pay-attention-to-1', 'pay-attention-to', 'Governments should pay attention to the problems faced by the elderly.', '政府应该关注老年人面临的问题。', 'pay attention to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raise-awareness-of-1', 'raise-awareness-of', 'Schools can raise awareness of healthy eating through practical cooking lessons.', '学校可以通过烹饪实践课提高学生对健康饮食的意识。', 'raise awareness of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('point-out-1', 'point-out', 'Critics point out that the policy could harm people on low incomes.', '批评者指出,这项政策可能损害低收入人群。', 'point out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('figure-out-1', 'figure-out', 'Young people need time to figure out what they really want to do.', '年轻人需要时间弄清楚自己真正想做什么。', 'figure out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('find-out-1', 'find-out', 'Teachers should find out why some students fall behind in class.', '老师应该查明一些学生在课堂上落后的原因。', 'find out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('look-into-1', 'look-into', 'The government should look into the causes of rising youth crime.', '政府应该调查青少年犯罪率上升的原因。', 'look into');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rule-out-1', 'rule-out', 'We cannot rule out the possibility that technology will replace most teachers.', '我们不能排除技术取代大多数教师的可能性。', 'rule out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('come-up-with-1', 'come-up-with', 'Governments must come up with new ways to reduce traffic in cities.', '政府必须想出新办法减少城市交通流量。', 'come up with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('put-forward-1', 'put-forward', 'Several solutions have been put forward to deal with the housing shortage.', '针对住房短缺,人们提出了几种解决办法。', 'put forward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('put-off-1', 'put-off', 'Many young couples put off having children for financial reasons.', '许多年轻夫妇因经济原因推迟生育。', 'put off');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('give-up-1', 'give-up', 'Some students give up their studies because they cannot afford the fees.', '有些学生因为付不起学费而放弃学业。', 'give up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-up-1', 'take-up', 'Doctors advise older people to take up gentle forms of exercise.', '医生建议老年人开始进行温和的运动。', 'take up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cut-down-on-1', 'cut-down-on', 'Individuals can cut down on waste by avoiding single-use plastic products.', '个人可以通过不使用一次性塑料制品来减少浪费。', 'cut down on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phase-out-1', 'phase-out', 'Many governments plan to phase out petrol cars within twenty years.', '许多国家的政府计划在二十年内逐步淘汰汽油车。', 'phase out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('run-out-of-1', 'run-out-of', 'The world may eventually run out of oil and natural gas.', '世界最终可能用完石油和天然气。', 'run out of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('break-down-1', 'break-down', 'Strong communities may break down when young people move away.', '年轻人搬走后,紧密的社区可能会瓦解。', 'break down');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dispose-of-1', 'dispose-of', 'Factories must dispose of their waste in a safe and legal way.', '工厂必须以安全合法的方式处理废物。', 'dispose of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('keep-up-with-1', 'keep-up-with', 'Older workers may find it difficult to keep up with new technology.', '年长的工人可能觉得很难跟上新技术。', 'keep up with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catch-up-on-1', 'catch-up-on', 'Many busy workers use their weekends to catch up on lost sleep.', '许多忙碌的上班族利用周末补觉。', 'catch up on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('look-forward-to-1', 'look-forward-to', 'Many people look forward to retirement, but some find it hard to adapt.', '许多人期待退休,但有些人很难适应。', 'look forward to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-responsible-for-1', 'be-responsible-for', 'Parents are responsible for the behaviour of their young children.', '父母要对年幼孩子的行为负责。', 'are responsible for');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-associated-with-1', 'be-associated-with', 'Long working hours are associated with poor physical and mental health.', '长时间工作与身心健康不佳有关。', 'are associated with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-related-to-1', 'be-related-to', 'Many health problems are related to a lack of regular exercise.', '许多健康问题与缺乏规律运动有关。', 'are related to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-subject-to-1', 'be-subject-to', 'Imported goods are subject to a tax of ten percent.', '进口商品须缴纳百分之十的税。', 'are subject to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-exposed-to-1', 'be-exposed-to', 'Children are exposed to too much advertising on the internet.', '孩子们在互联网上接触到太多广告。', 'are exposed to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-aware-of-1', 'be-aware-of', 'People should be aware of the dangers of sharing personal information online.', '人们应该意识到在网上分享个人信息的危险。', 'be aware of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-capable-of-1', 'be-capable-of', 'Young children are capable of learning several languages at the same time.', '幼儿能够同时学习几种语言。', 'are capable of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-likely-to-1', 'be-likely-to', 'Children from poor families are less likely to attend university.', '贫困家庭的孩子上大学的可能性较小。', 'are less likely to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-bound-to-1', 'be-bound-to', 'Rising prices are bound to affect people on low incomes most.', '物价上涨必然对低收入人群影响最大。', 'are bound to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-inclined-to-1', 'be-inclined-to', 'Many people are inclined to believe everything that they read online.', '许多人倾向于相信网上读到的一切。', 'are inclined to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-favour-of-1', 'in-favour-of', 'Many people are in favour of banning cars from city centres.', '许多人支持禁止汽车进入市中心。', 'in favour of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('at-the-expense-of-1', 'at-the-expense-of', 'Economic growth should not be achieved at the expense of the environment.', '不应以牺牲环境为代价实现经济增长。', 'at the expense of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-the-long-run-1', 'in-the-long-run', 'Investing in public transport will save money in the long run.', '从长远来看,投资公共交通可以省钱。', 'in the long run');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-the-short-term-1', 'in-the-short-term', 'Higher taxes may reduce spending in the short term.', '短期内,提高税收可能减少支出。', 'in the short term');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('as-a-result-1', 'as-a-result', 'Many young people move to cities; as a result, rural communities are shrinking.', '许多年轻人迁往城市,因此农村社区正在萎缩。', 'as a result');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('as-a-whole-1', 'as-a-whole', 'Better education benefits society as a whole, not only individual students.', '更好的教育有益于整个社会,而不仅是学生个人。', 'as a whole');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('on-the-other-hand-1', 'on-the-other-hand', 'Tourism creates jobs; on the other hand, it can damage the environment.', '旅游业创造就业机会;另一方面,它也可能破坏环境。', 'on the other hand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('on-the-whole-1', 'on-the-whole', 'On the whole, I believe that the benefits of technology outweigh its drawbacks.', '总的来说,我认为技术的好处大于坏处。', 'On the whole');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('by-contrast-1', 'by-contrast', 'Cars pollute the air; by contrast, bicycles produce no harmful gases.', '汽车污染空气;相比之下,自行车不产生有害气体。', 'by contrast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-conclusion-1', 'in-conclusion', 'In conclusion, governments should spend more money on public health.', '总之,政府应该在公共卫生上投入更多资金。', 'In conclusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('to-some-extent-1', 'to-some-extent', 'To some extent, parents are responsible for their children''s eating habits.', '在某种程度上,父母要对孩子的饮食习惯负责。', 'To some extent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('to-a-large-extent-1', 'to-a-large-extent', 'Success at school depends to a large extent on family support.', '在学校取得成功在很大程度上取决于家庭支持。', 'to a large extent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-particular-1', 'in-particular', 'Young people in particular are affected by the rising cost of housing.', '年轻人尤其受到住房成本上升的影响。', 'in particular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('for-instance-1', 'for-instance', 'Governments could, for instance, offer tax cuts to people who buy electric cars.', '例如,政府可以为购买电动汽车的人提供减税。', 'for instance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-other-words-1', 'in-other-words', 'Most jobs now require a degree; in other words, school alone is not enough.', '现在大多数工作都要求学位;换句话说,只读完中学是不够的。', 'in other words');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regardless-of-1', 'regardless-of', 'Every child should have access to good education regardless of family income.', '不论家庭收入如何,每个孩子都应该能接受良好的教育。', 'regardless of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-spite-of-1', 'in-spite-of', 'In spite of the high cost, many families choose to send their children abroad.', '尽管费用很高,许多家庭还是选择送孩子出国。', 'In spite of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instead-of-1', 'instead-of', 'More people should use public transport instead of driving to work.', '更多人应该乘坐公共交通,而不是开车上班。', 'instead of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rather-than-1', 'rather-than', 'Schools should teach students to think for themselves rather than memorise facts.', '学校应该教学生独立思考,而不是死记事实。', 'rather than');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('as-well-as-1', 'as-well-as', 'Exercise improves mental health as well as physical fitness.', '运动既能改善身体素质,也能改善心理健康。', 'as well as');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apart-from-1', 'apart-from', 'Apart from cost, there are few reasons for not using public transport.', '除了费用之外,几乎没有什么理由不乘坐公共交通。', 'Apart from');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('along-with-1', 'along-with', 'Exercise, along with a healthy diet, can greatly reduce the risk of illness.', '运动连同健康饮食,可以大大降低患病风险。', 'along with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-accordance-with-1', 'in-accordance-with', 'Companies must treat their employees in accordance with the law.', '公司必须依照法律对待员工。', 'in accordance with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('on-behalf-of-1', 'on-behalf-of', 'Unions negotiate with employers on behalf of their members.', '工会代表成员与雇主谈判。', 'on behalf of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-response-to-1', 'in-response-to', 'The government lowered the speed limit in response to public concern.', '针对公众的担忧,政府降低了限速。', 'in response to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-the-case-of-1', 'in-the-case-of', 'In the case of young children, too much screen time can harm sleep.', '就幼儿而言,过多的屏幕时间可能影响睡眠。', 'In the case of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('by-means-of-1', 'by-means-of', 'Many people now learn languages by means of mobile phone apps.', '现在许多人通过手机应用学习语言。', 'by means of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('education-1', 'education', 'Education is the most effective way to reduce poverty in the long term.', '从长远看,教育是减少贫困最有效的方法。', 'Education');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('academic-1', 'academic', 'Academic success does not always lead to a satisfying career.', '学术上的成功并不总能带来令人满意的职业。', 'Academic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('primary-school-1', 'primary-school', 'Foreign languages should be taught from the first year of primary school.', '外语应该从小学一年级开始教。', 'primary school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secondary-school-1', 'secondary-school', 'Many secondary school students feel under pressure to get high grades.', '许多中学生感到要取得高分的压力。', 'secondary school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tertiary-education-1', 'tertiary-education', 'Tertiary education should be free for students from poor families.', '贫困家庭的学生应该能免费接受高等教育。', 'Tertiary education');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('higher-education-1', 'higher-education', 'More young people than ever now have access to higher education.', '现在能接受高等教育的年轻人比以往任何时候都多。', 'higher education');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vocational-1', 'vocational', 'Vocational courses can prepare young people well for skilled jobs.', '职业课程能帮助年轻人为技术工作做好准备。', 'Vocational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vocational-training-1', 'vocational-training', 'Vocational training is often more useful than a university degree for some jobs.', '对某些工作来说,职业培训往往比大学学位更有用。', 'Vocational training');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kindergarten-1', 'kindergarten', 'Children who attend kindergarten often settle more easily into primary school.', '上过幼儿园的孩子往往更容易适应小学。', 'kindergarten');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preschool-1', 'preschool', 'Preschool education helps young children to develop social and language skills.', '学龄前教育帮助幼儿发展社交和语言能力。', 'Preschool');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pupil-1', 'pupil', 'Each pupil should have the chance to take part in sports at school.', '每个学生都应该有机会在学校参加体育活动。', 'pupil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('graduate-1', 'graduate', 'Many graduates find it difficult to get a job in their chosen field.', '许多毕业生很难在自己选择的领域找到工作。', 'graduates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('graduate-2', 'graduate', 'Students who graduate with heavy debts may delay buying their own homes.', '背负沉重债务毕业的学生可能推迟买房。', 'graduate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dropout-1', 'dropout', 'A school dropout is much more likely to face unemployment later in life.', '辍学者日后面临失业的可能性要大得多。', 'dropout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compulsory-education-1', 'compulsory-education', 'Compulsory education should continue until the age of eighteen.', '义务教育应该延续到十八岁。', 'Compulsory education');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('state-school-1', 'state-school', 'Many parents believe that a state school can offer an equally good education.', '许多家长认为,公立学校同样能提供良好的教育。', 'state school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('private-school-1', 'private-school', 'Families who choose a private school often pay very high fees.', '选择私立学校的家庭往往要支付很高的费用。', 'private school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boarding-school-1', 'boarding-school', 'Some children find it hard to live away from home at boarding school.', '有些孩子觉得在寄宿学校离家生活很难。', 'boarding school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('single-sex-school-1', 'single-sex-school', 'Some people argue that girls do better in a single-sex school.', '有些人认为女孩在单性别学校表现更好。', 'single-sex school');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('co-educational-1', 'co-educational', 'Co-educational schools help boys and girls to learn how to work together.', '男女同校有助于男孩和女孩学会合作。', 'Co-educational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homeschooling-1', 'homeschooling', 'Homeschooling allows parents to choose what and how their children learn.', '在家教育让父母能选择孩子学什么和怎么学。', 'Homeschooling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distance-learning-1', 'distance-learning', 'Distance learning allows people in remote areas to study for a degree.', '远程教育让偏远地区的人也能攻读学位。', 'Distance learning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('e-learning-1', 'e-learning', 'E-learning offers flexibility, but some students miss direct contact with teachers.', '在线学习提供了灵活性,但有些学生怀念与老师的直接接触。', 'E-learning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lifelong-learning-1', 'lifelong-learning', 'Lifelong learning has become essential because skills change so quickly.', '由于技能变化太快,终身学习已变得至关重要。', 'Lifelong learning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pedagogy-1', 'pedagogy', 'Good pedagogy matters more than expensive equipment in the classroom.', '在课堂上,好的教学法比昂贵的设备更重要。', 'pedagogy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instruct-1', 'instruct', 'Teachers should instruct children in how to use the internet safely.', '老师应该教导孩子如何安全地使用互联网。', 'instruct');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instruction-1', 'instruction', 'Students receive instruction in both English and their native language.', '学生接受英语和母语两种语言的教学。', 'instruction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rote-learning-1', 'rote-learning', 'Rote learning may help students pass exams but does not develop understanding.', '死记硬背也许能帮学生通过考试,但不能增进理解。', 'Rote learning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('memorise-1', 'memorise', 'Students should do more than simply memorise facts for an exam.', '学生不应该只是为了考试而记住事实。', 'memorise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spoon-feeding-1', 'spoon-feeding', 'Spoon-feeding students leaves them unable to solve problems by themselves.', '填鸭式教学使学生无法独立解决问题。', 'Spoon-feeding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('critical-thinking-1', 'critical-thinking', 'Schools should place more emphasis on developing critical thinking.', '学校应该更加重视培养批判性思维。', 'critical thinking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('problem-solving-1', 'problem-solving', 'Group projects are an excellent way of teaching problem-solving skills.', '小组项目是培养解决问题能力的极好方法。', 'problem-solving');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('analytical-1', 'analytical', 'Studying mathematics helps children to develop strong analytical skills.', '学习数学有助于孩子培养强大的分析能力。', 'analytical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('creative-1', 'creative', 'Art and music lessons encourage children to be more creative.', '美术和音乐课鼓励孩子更有创造力。', 'creative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('all-round-1', 'all-round', 'Schools should aim to provide an all-round education for every child.', '学校应该致力于为每个孩子提供全面的教育。', 'all-round');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-rounded-1', 'well-rounded', 'Sports and the arts help students to become well-rounded adults.', '体育和艺术帮助学生成长为全面发展的成年人。', 'well-rounded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extracurricular-1', 'extracurricular', 'Extracurricular clubs give students a chance to develop new interests.', '课外社团让学生有机会培养新的兴趣。', 'Extracurricular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('academic-performance-1', 'academic-performance', 'Some studies suggest that regular exercise can improve academic performance.', '一些研究表明,经常锻炼可以提高学业表现。', 'academic performance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('achievement-1', 'achievement', 'Family income has a strong influence on a child''s achievement at school.', '家庭收入对孩子在学校的成就有很大影响。', 'achievement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intellectual-1', 'intellectual', 'Puzzles and games can support the intellectual development of young children.', '拼图和游戏可以促进幼儿的智力发展。', 'intellectual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intellectual-2', 'intellectual', 'Intellectuals have often played an important part in political change.', '知识分子常常在政治变革中发挥重要作用。', 'Intellectuals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('knowledge-1', 'knowledge', 'Practical skills are often as valuable as knowledge gained from books.', '实践技能往往和书本知识一样宝贵。', 'knowledge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('competence-1', 'competence', 'Students should reach a basic level of competence in computer skills.', '学生的计算机能力应该达到基本水平。', 'competence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proficiency-1', 'proficiency', 'A high level of proficiency in English can open many doors.', '高水平的英语熟练度能打开许多大门。', 'proficiency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aptitude-1', 'aptitude', 'Children with an aptitude for music should be given extra support.', '有音乐天资的孩子应该得到额外支持。', 'aptitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('talent-1', 'talent', 'Schools should help every child to discover their natural talent.', '学校应该帮助每个孩子发现自己的天赋。', 'talent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gifted-1', 'gifted', 'Gifted children can become bored if lessons are too easy for them.', '如果课程太简单,有天赋的孩子可能会感到无聊。', 'Gifted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obedient-1', 'obedient', 'Traditional schools often valued obedient students more than creative ones.', '传统学校往往更看重顺从的学生,而不是有创造力的学生。', 'obedient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rebellious-1', 'rebellious', 'Teenagers can become rebellious if parents set too many strict rules.', '如果父母定下太多严格的规矩,青少年可能变得叛逆。', 'rebellious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('truant-1', 'truant', 'A persistent truant is more likely to become involved in crime.', '长期逃学者更有可能卷入犯罪。', 'truant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bullying-1', 'bullying', 'Schools must take strong action against all forms of bullying.', '学校必须采取有力行动,打击各种形式的欺凌。', 'bullying');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('class-size-1', 'class-size', 'Reducing class size allows teachers to give each student more attention.', '缩小班级规模让老师能给每个学生更多关注。', 'class size');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('teacher-student-ratio-1', 'teacher-student-ratio', 'A low teacher-student ratio can make it hard for pupils to get help.', '师生比低会使学生很难得到帮助。', 'teacher-student ratio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('educator-1', 'educator', 'Every educator knows that children learn in different ways.', '每位教育工作者都知道孩子们的学习方式各不相同。', 'educator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mentor-1', 'mentor', 'An experienced mentor can help young workers to develop their careers.', '经验丰富的导师能帮助年轻员工发展事业。', 'mentor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('role-model-1', 'role-model', 'Teachers can be an important role model for young people.', '老师可以成为年轻人重要的榜样。', 'role model');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('qualified-1', 'qualified', 'Every school needs enough qualified teachers in science and mathematics.', '每所学校都需要足够的合格的科学和数学教师。', 'qualified');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('standardised-test-1', 'standardised-test', 'A standardised test cannot measure every skill that students need.', '标准化考试无法衡量学生需要的每一项技能。', 'standardised test');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exam-oriented-1', 'exam-oriented', 'An exam-oriented system leaves little time for art, music and sports.', '应试制度几乎不给美术、音乐和体育留时间。', 'exam-oriented');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tuition-1', 'tuition', 'The cost of university tuition has risen sharply in many countries.', '在许多国家,大学学费急剧上涨。', 'tuition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('student-loan-1', 'student-loan', 'A student loan can take many years to pay back after graduation.', '学生贷款可能要在毕业后很多年才能还清。', 'student loan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gap-year-1', 'gap-year', 'A gap year can give young people valuable experience of the wider world.', '间隔年能让年轻人获得了解更广阔世界的宝贵经验。', 'gap year');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('study-abroad-1', 'study-abroad', 'Students who study abroad often gain independence and new language skills.', '出国留学的学生常常变得更独立,并掌握新的语言技能。', 'study abroad');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brain-drain-1', 'brain-drain', 'The brain drain has left many poor countries short of doctors.', '人才流失使许多贫穷国家缺少医生。', 'brain drain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equal-opportunity-1', 'equal-opportunity', 'Governments should ensure equal opportunity in education for boys and girls.', '政府应该确保男孩和女孩在教育上机会均等。', 'equal opportunity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('numeracy-1', 'numeracy', 'Basic numeracy is essential for managing money in everyday life.', '基本计算能力对日常生活中的理财至关重要。', 'numeracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illiteracy-1', 'illiteracy', 'Illiteracy remains a serious barrier to economic progress in some countries.', '文盲仍然是一些国家经济发展的严重障碍。', 'Illiteracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('educational-1', 'educational', 'Some television programmes have a clear educational value for young children.', '一些电视节目对幼儿有明显的教育价值。', 'educational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('didactic-1', 'didactic', 'Young readers often dislike stories that are too didactic.', '年轻读者常常不喜欢过于说教的故事。', 'didactic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disobedient-1', 'disobedient', 'Disobedient children often need clear rules rather than harsh punishment.', '不听话的孩子往往需要明确的规则,而不是严厉的惩罚。', 'Disobedient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('classics-1', 'classics', 'Students should still read the classics, even in the age of the internet.', '即使在互联网时代,学生也应该读经典著作。', 'classics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('team-spirit-1', 'team-spirit', 'Team sports help children to develop a strong team spirit.', '团队运动帮助孩子培养强烈的团队精神。', 'team spirit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extracurricular-activities-1', 'extracurricular-activities', 'Extracurricular activities can improve a student''s confidence and social skills.', '课外活动可以增强学生的自信心和社交能力。', 'Extracurricular activities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mass-media-1', 'mass-media', 'The mass media has a strong influence on public opinion about politics.', '大众媒体对公众的政治看法有很大影响。', 'mass media');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('media-1', 'media', 'The media should be free to criticise those in power.', '媒体应该可以自由批评当权者。', 'media');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('press-1', 'press', 'A free press is essential to any healthy democracy.', '自由的新闻界对任何健康的民主国家都必不可少。', 'press');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('press-2', 'press', 'Simply press the button to speak to a member of staff.', '只需按下按钮,就能和工作人员通话。', 'press');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('journalism-1', 'journalism', 'Good journalism helps people to understand complex social problems.', '好的新闻业帮助人们理解复杂的社会问题。', 'journalism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('journalist-1', 'journalist', 'A journalist should check the facts carefully before publishing a story.', '记者在发表报道前应仔细核实事实。', 'journalist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reporter-1', 'reporter', 'The reporter spent a year investigating conditions in the country''s prisons.', '这名记者花了一年时间调查该国监狱的状况。', 'reporter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('editor-1', 'editor', 'The editor decides which stories will appear on the front page.', '编辑决定哪些报道登上头版。', 'editor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('headline-1', 'headline', 'A shocking headline can attract readers even when the story is unimportant.', '即使报道并不重要,耸人听闻的标题也能吸引读者。', 'headline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coverage-1', 'coverage', 'News coverage of crime can make people feel less safe than they are.', '关于犯罪的新闻报道可能让人们感觉比实际情况更不安全。', 'coverage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('broadcast-1', 'broadcast', 'Television stations should broadcast more programmes about science.', '电视台应该播放更多科学节目。', 'broadcast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('channel-1', 'channel', 'Some people get their news from a single television channel.', '有些人只从一个电视频道获取新闻。', 'channel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('documentary-1', 'documentary', 'A good documentary can make young people care about the environment.', '一部好的纪录片能让年轻人关心环境。', 'documentary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tabloid-1', 'tabloid', 'Tabloid newspapers often focus on the private lives of famous people.', '小报常常关注名人的私生活。', 'Tabloid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('broadsheet-1', 'broadsheet', 'A broadsheet usually offers more serious news than a popular daily paper.', '大报通常提供比流行日报更严肃的新闻。', 'broadsheet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('censorship-1', 'censorship', 'Censorship of the internet limits people''s access to information.', '互联网审查限制了人们获取信息。', 'Censorship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freedom-of-speech-1', 'freedom-of-speech', 'Freedom of speech does not mean that people may say anything at all.', '言论自由并不意味着人们可以说任何话。', 'Freedom of speech');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('propaganda-1', 'propaganda', 'Governments have often used propaganda to win support during wars.', '政府经常在战争期间利用宣传赢得支持。', 'propaganda');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('misinformation-1', 'misinformation', 'Misinformation spreads quickly on the internet and can be hard to correct.', '错误信息在互联网上传播很快,而且很难纠正。', 'Misinformation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fake-news-1', 'fake-news', 'Schools should teach children how to recognise fake news online.', '学校应该教孩子如何识别网上的假新闻。', 'fake news');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sensational-1', 'sensational', 'Some newspapers publish sensational stories simply to attract more readers.', '一些报纸刊登耸人听闻的报道,只是为了吸引更多读者。', 'sensational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biased-1', 'biased', 'News reports may be biased in favour of those who own the media.', '新闻报道可能偏袒媒体的所有者。', 'biased');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('objective-reporting-1', 'objective-reporting', 'Objective reporting is difficult when journalists have strong political views.', '当记者有强烈的政治观点时,很难做到客观报道。', 'Objective reporting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-media-1', 'social-media', 'Social media makes it easy to stay in touch with friends abroad.', '社交媒体让人们很容易与国外的朋友保持联系。', 'Social media');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('influencer-1', 'influencer', 'Many teenagers buy products simply because an influencer recommends them.', '许多青少年买东西只是因为网红推荐。', 'influencer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('celebrity-1', 'celebrity', 'Young people are often too interested in the lives of each celebrity.', '年轻人常常对每位名人的生活过于感兴趣。', 'celebrity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paparazzi-1', 'paparazzi', 'The paparazzi follow famous people everywhere in search of photographs.', '狗仔队到处跟踪名人,想要拍照。', 'paparazzi');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intrusion-1', 'intrusion', 'Publishing private photographs is a serious intrusion into a person''s life.', '发布私人照片是对个人生活的严重侵扰。', 'intrusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('addiction-1', 'addiction', 'Internet addiction can seriously affect the health of young people.', '网瘾可能严重影响年轻人的健康。', 'addiction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('addicted-1', 'addicted', 'Many children have become addicted to computer games and social media.', '许多孩子沉迷于电脑游戏和社交媒体。', 'addicted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('screen-time-1', 'screen-time', 'Parents should limit the screen time of their young children.', '父母应该限制年幼孩子的屏幕使用时间。', 'screen time');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('digital-divide-1', 'digital-divide', 'The digital divide leaves poorer families without the same access to information.', '数字鸿沟使较贫困家庭无法同样获取信息。', 'digital divide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('information-overload-1', 'information-overload', 'Information overload makes it harder for people to concentrate on one task.', '信息过载使人们更难专注于一项任务。', 'Information overload');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('connectivity-1', 'connectivity', 'Better connectivity allows people in rural areas to work from home.', '更好的网络连接让农村地区的人们可以在家工作。', 'connectivity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instant-1', 'instant', 'Instant messaging has reduced the amount of time people spend talking face to face.', '即时通讯减少了人们当面交谈的时间。', 'Instant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convenient-1', 'convenient', 'Online shopping is convenient, but it may harm local businesses.', '网购很方便,但可能损害本地商家。', 'convenient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accessible-1', 'accessible', 'The internet has made higher education accessible to people in remote areas.', '互联网让偏远地区的人们也能接受高等教育。', 'accessible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('access-1', 'access', 'Everyone should have access to clean water and basic health care.', '每个人都应该能获得清洁的水和基本医疗。', 'access');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('access-2', 'access', 'Students can access the library''s books from any computer on the campus.', '学生可以从校园里的任何电脑访问图书馆的书籍。', 'access');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dependence-1', 'dependence', 'Our growing dependence on technology may reduce our basic skills.', '我们对技术日益增长的依赖可能削弱基本技能。', 'dependence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('isolation-1', 'isolation', 'Spending too much time online can lead to social isolation.', '上网时间过长可能导致社交孤立。', 'isolation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('face-to-face-1', 'face-to-face', 'Nothing can fully replace face-to-face communication between teachers and students.', '没有什么能完全取代师生之间面对面的交流。', 'face-to-face');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interpersonal-1', 'interpersonal', 'Too much time on phones may weaken children''s interpersonal skills.', '花太多时间在手机上可能削弱孩子的人际交往能力。', 'interpersonal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revolutionise-1', 'revolutionise', 'Mobile phones have revolutionised the way people communicate with each other.', '手机彻底改变了人们相互交流的方式。', 'revolutionised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('job-displacement-1', 'job-displacement', 'Job displacement caused by automation is a serious concern for many workers.', '自动化造成的工作岗位被替代是许多工人严重担忧的问题。', 'Job displacement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surveillance-1', 'surveillance', 'Increased surveillance may reduce crime, but it also threatens personal privacy.', '加强监控也许能减少犯罪,但也威胁个人隐私。', 'surveillance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ethical-1', 'ethical', 'There are serious ethical questions about the use of genetic information.', '基因信息的使用存在严重的道德问题。', 'ethical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ethics-1', 'ethics', 'Journalists have a code of ethics that they are expected to follow.', '记者有一套应当遵守的伦理准则。', 'ethics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scandal-1', 'scandal', 'A political scandal can damage public trust in the entire government.', '政治丑闻可能损害公众对整个政府的信任。', 'scandal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gossip-1', 'gossip', 'Many magazines are filled with gossip about the private lives of celebrities.', '许多杂志充斥着有关名人私生活的八卦。', 'gossip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rumour-1', 'rumour', 'A false rumour can spread around the world within a few hours.', '虚假的谣言可能在几小时内传遍全球。', 'rumour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exposure-1', 'exposure', 'Too much exposure to violent films may affect the behaviour of children.', '过多接触暴力电影可能影响孩子的行为。', 'exposure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disclosure-1', 'disclosure', 'Companies should be required to make a full disclosure of their finances.', '公司应被要求全面披露财务状况。', 'disclosure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('newsworthy-1', 'newsworthy', 'Editors tend to think that bad news is more newsworthy than good news.', '编辑往往认为坏消息比好消息更有新闻价值。', 'newsworthy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fabricated-1', 'fabricated', 'Readers may lose trust when a newspaper publishes a fabricated story.', '报纸刊登捏造的报道时,读者可能失去信任。', 'fabricated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exaggerated-1', 'exaggerated', 'The risks of the new technology have often been exaggerated by the media.', '媒体常常夸大这项新技术的风险。', 'exaggerated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('truthful-1', 'truthful', 'Advertisements should be truthful about what a product can actually do.', '广告应该如实说明产品的实际功效。', 'truthful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deceitful-1', 'deceitful', 'Deceitful advertising can persuade people to buy things they do not need.', '欺骗性广告可能诱使人们购买不需要的东西。', 'Deceitful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hypocritical-1', 'hypocritical', 'It seems hypocritical for rich countries to criticise the emissions of poorer ones.', '富国批评穷国的排放,似乎很虚伪。', 'hypocritical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('objectivity-1', 'objectivity', 'The objectivity of the report was questioned because of who paid for it.', '由于资助方的身份,这份报告的客观性受到质疑。', 'objectivity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('readability-1', 'readability', 'Short sentences can improve the readability of a report.', '短句可以提高报告的可读性。', 'readability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('informative-1', 'informative', 'Informative programmes can be just as entertaining as other types of television.', '信息丰富的节目可以和其他类型的电视节目一样有趣。', 'Informative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correspondent-1', 'correspondent', 'The newspaper''s foreign correspondent reported directly from the war zone.', '这家报纸的驻外通讯记者从战区直接发回报道。', 'correspondent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('columnist-1', 'columnist', 'One columnist argued that the government should do more for young people.', '一位专栏作家认为,政府应该为年轻人做更多事情。', 'columnist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('editorial-1', 'editorial', 'An editorial in the national newspaper criticised the new tax.', '全国性报纸的一篇社论批评了这项新税。', 'editorial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spokesman-1', 'spokesman', 'A government spokesman denied that the policy would be changed.', '一位政府发言人否认这项政策会改变。', 'spokesman');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('caricature-1', 'caricature', 'The newspaper printed a caricature of the prime minister on its front page.', '这家报纸在头版刊登了一幅首相的讽刺漫画。', 'caricature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('billboard-1', 'billboard', 'A large billboard beside the road can distract drivers and cause accidents.', '路边的大广告牌可能分散司机的注意力,引发事故。', 'billboard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brainwashing-1', 'brainwashing', 'Some critics describe constant advertising as a form of brainwashing.', '一些批评者把持续不断的广告说成是一种洗脑。', 'brainwashing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('idol-1', 'idol', 'Teenagers often copy the clothes and behaviour of their favourite idol.', '青少年常常模仿他们最喜欢的偶像的衣着和行为。', 'idol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indulge-1', 'indulge', 'Parents who indulge their children may make it harder for them to cope later.', '纵容孩子的父母可能让孩子日后更难应对问题。', 'indulge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pornography-1', 'pornography', 'Parents worry about their children finding pornography on the internet.', '父母担心孩子在互联网上看到色情内容。', 'pornography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tempting-1', 'tempting', 'It is tempting for young people to buy things they cannot afford.', '对年轻人来说,买自己负担不起的东西很诱人。', 'tempting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irresistible-1', 'irresistible', 'Advertising can make unhealthy snacks seem irresistible to young children.', '广告能让不健康的零食对幼儿来说显得无法抗拒。', 'irresistible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immature-1', 'immature', 'Teenagers may be too immature to make such important decisions by themselves.', '青少年可能还太不成熟,无法独自作出如此重要的决定。', 'immature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('naive-1', 'naive', 'It is naive to believe everything that appears on the internet.', '相信网上的一切是很天真的。', 'naive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('questionable-1', 'questionable', 'The company''s claims about its environmental record are highly questionable.', '该公司关于其环保记录的说法非常可疑。', 'questionable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alarming-1', 'alarming', 'The number of young people with mental health problems has reached alarming levels.', '有心理健康问题的年轻人数量已达到令人担忧的水平。', 'alarming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disturbing-1', 'disturbing', 'There is a disturbing rise in the amount of violence on television.', '电视上的暴力内容令人不安地增多了。', 'disturbing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prevalence-1', 'prevalence', 'The prevalence of mobile phones has changed how young people spend their time.', '手机的盛行改变了年轻人度过时间的方式。', 'prevalence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blockbuster-1', 'blockbuster', 'A Hollywood blockbuster can earn more than the budget of a small country.', '一部好莱坞大片的收入可能超过一个小国的预算。', 'blockbuster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('premiere-1', 'premiere', 'The film''s premiere attracted a large crowd of fans to the city.', '这部电影的首映吸引了大批影迷来到这座城市。', 'premiere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trailer-1', 'trailer', 'A good trailer can persuade millions of people to see a film.', '一部好的预告片能说服数百万人去看电影。', 'trailer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('playwright-1', 'playwright', 'The playwright''s works are still performed in theatres around the world.', '这位剧作家的作品至今仍在世界各地的剧院上演。', 'playwright');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('musical-1', 'musical', 'Tourists to London often go to see a musical during their stay.', '到伦敦的游客在逗留期间常常去看音乐剧。', 'musical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('climax-1', 'climax', 'The climax of the film comes in the final fifteen minutes.', '这部电影的高潮出现在最后十五分钟。', 'climax');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('applause-1', 'applause', 'The audience gave the young actors a long round of applause.', '观众为年轻演员们报以长时间的掌声。', 'applause');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('press-conference-1', 'press-conference', 'The minister announced the new policy at a press conference this morning.', '部长今天上午在新闻发布会上宣布了新政策。', 'press conference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prime-time-1', 'prime-time', 'Advertisements during prime time reach the largest number of viewers.', '黄金时段的广告能触达最多的观众。', 'prime time');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('best-seller-1', 'best-seller', 'Her first novel became a best-seller in more than twenty countries.', '她的第一部小说在二十多个国家成为畅销书。', 'best-seller');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('time-consuming-1', 'time-consuming', 'Filling in these official forms is a slow and time-consuming process.', '填写这些官方表格是一个缓慢而耗时的过程。', 'time-consuming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forum-1', 'forum', 'Online forums allow people with similar problems to share their experiences.', '网络论坛让有相似问题的人能够分享经验。', 'forums');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credibility-1', 'credibility', 'The newspaper lost its credibility after publishing several false stories.', '这家报纸刊登了几篇虚假报道后失去了可信度。', 'credibility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clip-1', 'clip', 'A short video clip can spread around the world within hours.', '一段短视频可能在几小时内传遍全球。', 'clip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commentary-1', 'commentary', 'The programme included live commentary from two former players.', '这个节目有两位前球员的现场解说。', 'commentary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('messenger-1', 'messenger', 'Before the telephone, important news was carried by a messenger on horseback.', '电话出现之前,重要消息由骑马的信使传递。', 'messenger');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('publicity-1', 'publicity', 'The company gained a great deal of publicity from the charity event.', '这家公司通过这次慈善活动获得了大量宣传。', 'publicity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('publication-1', 'publication', 'The publication of the report led to a public debate on school meals.', '这份报告的发表引发了关于学校午餐的公众讨论。', 'publication');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fame-1', 'fame', 'Many young people dream of fame and wealth as social media stars.', '许多年轻人梦想成为社交媒体明星,获得名声和财富。', 'fame');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pamphlet-1', 'pamphlet', 'The health department sent a pamphlet to every home in the region.', '卫生部门向该地区每户家庭发送了一本小册子。', 'pamphlet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('government-1', 'government', 'The government should provide free health care for all its citizens.', '政府应该为所有公民提供免费医疗。', 'government');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('authority-1', 'authority', 'The local authority is responsible for collecting household waste.', '地方当局负责收集生活垃圾。', 'authority');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('administration-1', 'administration', 'The new administration promised to spend more on public transport.', '新政府承诺在公共交通上投入更多资金。', 'administration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('policy-1', 'policy', 'A policy of free public transport could reduce traffic in city centres.', '免费公共交通政策可以减少市中心的交通流量。', 'policy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('policymaker-1', 'policymaker', 'Every policymaker should consider the long-term effects of new laws.', '每位决策者都应该考虑新法律的长期影响。', 'policymaker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legislation-1', 'legislation', 'New legislation is needed to protect workers in the digital economy.', '需要新的立法来保护数字经济中的工人。', 'legislation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legislate-1', 'legislate', 'Governments should legislate against the sale of unhealthy food in schools.', '政府应该立法禁止在学校出售不健康食品。', 'legislate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regulation-1', 'regulation', 'Stricter regulation of the banks could prevent another financial crisis.', '加强对银行的管理可以防止再次发生金融危机。', 'regulation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parliament-1', 'parliament', 'Parliament will vote on the proposed changes to the tax system next week.', '议会下周将就税收制度的修改提案进行投票。', 'Parliament');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('democracy-1', 'democracy', 'In a democracy, people have the right to choose their own leaders.', '在民主国家,人民有权选择自己的领导人。', 'democracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('democratic-1', 'democratic', 'Free elections are the foundation of any democratic system.', '自由选举是任何民主制度的基础。', 'democratic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('election-1', 'election', 'Young people are less likely to vote in a national election.', '年轻人在全国选举中投票的可能性较小。', 'election');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vote-1', 'vote', 'Some people believe that the age to vote should be lowered to sixteen.', '有些人认为投票年龄应该降低到十六岁。', 'vote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('political-1', 'political', 'Young people should take more interest in political issues.', '年轻人应该更关注政治问题。', 'political');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('politician-1', 'politician', 'A politician should be judged on actions rather than promises.', '评价政治家应该看行动,而不是承诺。', 'politician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('citizen-1', 'citizen', 'Every citizen has a duty to obey the law and pay tax.', '每个公民都有义务遵守法律和纳税。', 'citizen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('citizenship-1', 'citizenship', 'Lessons in citizenship teach young people about their rights and duties.', '公民课教导年轻人了解自己的权利和义务。', 'citizenship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('civic-1', 'civic', 'Voting is one of the most important civic duties in a democracy.', '投票是民主国家最重要的公民义务之一。', 'civic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-sector-1', 'public-sector', 'Pay in the public sector is often lower than in private companies.', '公共部门的工资通常低于私营公司。', 'public sector');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('private-sector-1', 'private-sector', 'The private sector can often provide these services more efficiently.', '私营部门往往能更高效地提供这些服务。', 'private sector');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-services-1', 'public-services', 'Higher taxes are needed to pay for better public services.', '需要提高税收来支付更好的公共服务。', 'public services');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('welfare-1', 'welfare', 'The welfare system should support people who are unable to work.', '福利制度应该支持无法工作的人。', 'welfare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-security-1', 'social-security', 'An ageing population puts increasing pressure on the social security system.', '人口老龄化给社会保障体系带来越来越大的压力。', 'social security');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('healthcare-1', 'healthcare', 'Free healthcare should be available to everyone, regardless of income.', '无论收入如何,每个人都应该能享受免费医疗保健。', 'healthcare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('funding-1', 'funding', 'Schools in poor areas should receive more funding from the government.', '贫困地区的学校应该从政府获得更多资金。', 'funding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fund-1', 'fund', 'Governments should fund research into cleaner forms of energy.', '政府应该资助清洁能源研究。', 'fund');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fund-2', 'fund', 'A special fund has been created to help families who lost their homes.', '已设立专项基金帮助失去家园的家庭。', 'fund');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('taxpayer-1', 'taxpayer', 'Every taxpayer has the right to know how public money is spent.', '每位纳税人都有权知道公共资金的使用情况。', 'taxpayer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-money-1', 'public-money', 'Public money should not be spent on art when hospitals need more staff.', '医院还需要更多人手时,公共资金不应该花在艺术上。', 'Public money');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('priority-1', 'priority', 'Improving public health should be the top priority of any government.', '改善公共卫生应该是任何政府的首要事项。', 'priority');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prioritise-1', 'prioritise', 'Governments should prioritise education and health over military spending.', '政府应该优先考虑教育和医疗,而不是军费开支。', 'prioritise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intervene-1', 'intervene', 'Governments should intervene when companies charge unfair prices.', '当公司收取不公平的价格时,政府应该干预。', 'intervene');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intervention-1', 'intervention', 'Early intervention can prevent small problems from becoming much more serious.', '早期干预可以防止小问题发展得更严重。', 'intervention');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enforce-1', 'enforce', 'Police must enforce the law fairly, whoever is involved.', '无论涉及何人,警方都必须公正执法。', 'enforce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impose-1', 'impose', 'The government could impose a tax on foods with a high sugar content.', '政府可以对高糖食品征税。', 'impose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subsidise-1', 'subsidise', 'Governments should subsidise public transport so that fares remain low.', '政府应该补贴公共交通,使票价保持在低水平。', 'subsidise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invest-in-1', 'invest-in', 'Governments should invest in renewable energy rather than coal and oil.', '政府应该投资于可再生能源,而不是煤炭和石油。', 'invest in');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bureaucracy-1', 'bureaucracy', 'Too much bureaucracy can make it difficult to start a small business.', '官僚主义过重可能使创办小企业变得困难。', 'bureaucracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corruption-1', 'corruption', 'Corruption takes money away from schools, hospitals and other public services.', '腐败使学校、医院和其他公共服务失去资金。', 'Corruption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transparency-1', 'transparency', 'Greater transparency would make the government more accountable to the public.', '提高透明度将使政府对公众更负责任。', 'transparency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accountability-1', 'accountability', 'There should be more accountability in the way public money is spent.', '公共资金的使用应该有更多问责。', 'accountability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reform-1', 'reform', 'The education system is badly in need of reform.', '教育体系急需改革。', 'reform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reform-2', 'reform', 'Many people believe that the government must reform the prison system.', '许多人认为政府必须改革监狱制度。', 'reform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('initiative-1', 'initiative', 'The new initiative aims to reduce the amount of plastic used in schools.', '这项新举措旨在减少学校的塑料用量。', 'initiative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('campaign-1', 'campaign', 'A national campaign has helped to reduce the number of people who smoke.', '一场全国性运动帮助减少了吸烟人数。', 'campaign');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-awareness-1', 'public-awareness', 'Governments should raise public awareness of the dangers of a poor diet.', '政府应该提高公众对不良饮食危害的认识。', 'public awareness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diplomacy-1', 'diplomacy', 'Diplomacy is always better than military action in solving international conflicts.', '解决国际冲突时,外交总是好于军事行动。', 'Diplomacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sovereignty-1', 'sovereignty', 'Some people fear that globalisation reduces the sovereignty of smaller nations.', '有些人担心全球化削弱小国的主权。', 'sovereignty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('national-security-1', 'national-security', 'Governments sometimes limit personal freedom for reasons of national security.', '政府有时出于国家安全的原因限制个人自由。', 'national security');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('military-1', 'military', 'Some countries require young people to complete a period of military service.', '有些国家要求年轻人服一段时间的兵役。', 'military');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defence-1', 'defence', 'Spending on defence takes money away from education and health.', '国防开支占用了教育和医疗的资金。', 'defence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conflict-1', 'conflict', 'Conflict in the region has forced many families to leave their homes.', '该地区的冲突迫使许多家庭离开家园。', 'Conflict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refugee-1', 'refugee', 'Wealthy nations should do more to help each refugee build a new life.', '富裕国家应该做更多的事,帮助每位难民开始新生活。', 'refugee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humanitarian-1', 'humanitarian', 'Humanitarian organisations provide food and medicine in areas affected by war.', '人道主义组织在受战争影响的地区提供食物和药品。', 'Humanitarian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aid-1', 'aid', 'Foreign aid should be spent on projects that help people become independent.', '外国援助应该用于帮助人们实现自立的项目。', 'aid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('non-governmental-organisation-1', 'non-governmental-organisation', 'A non-governmental organisation can often respond quickly in an emergency.', '非政府组织在紧急情况下往往能迅速作出反应。', 'non-governmental organisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legislator-1', 'legislator', 'Each legislator must balance the needs of different groups in society.', '每位立法者都必须平衡社会不同群体的需求。', 'legislator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('senate-1', 'senate', 'The Senate rejected the proposal to raise the national minimum wage.', '参议院否决了提高全国最低工资的提案。', 'Senate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('congress-1', 'congress', 'Congress passed a new law to protect the country''s national parks.', '国会通过了一项保护国家公园的新法律。', 'Congress');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('committee-1', 'committee', 'A special committee was formed to study the causes of youth crime.', '成立了一个特别委员会来研究青少年犯罪的原因。', 'committee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ballot-1', 'ballot', 'Citizens cast their ballot in secret to ensure a fair election.', '公民以无记名方式投票,以确保选举公平。', 'ballot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ideology-1', 'ideology', 'Political ideology should not influence what is taught in schools.', '政治意识形态不应影响学校教授的内容。', 'ideology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regime-1', 'regime', 'The old regime was replaced after years of protests by ordinary people.', '经过普通民众多年的抗议,旧政权被取代了。', 'regime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('autonomy-1', 'autonomy', 'Universities should have greater autonomy in deciding what they teach.', '大学在决定教学内容方面应该有更大的自主权。', 'autonomy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('privilege-1', 'privilege', 'Education should be a basic right rather than a privilege of the rich.', '教育应该是基本权利,而不是富人的特权。', 'privilege');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nationality-1', 'nationality', 'Discrimination based on nationality should not be allowed in the workplace.', '工作场所不应允许基于国籍的歧视。', 'nationality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('republican-1', 'republican', 'The country adopted a republican system after the end of the monarchy.', '君主制结束后,这个国家采用了共和制度。', 'republican');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amendment-1', 'amendment', 'An amendment to the law now gives women equal rights to property.', '法律的一项修正案现在赋予女性平等的财产权。', 'amendment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decree-1', 'decree', 'The president issued a decree banning all public meetings.', '总统颁布法令,禁止一切公开集会。', 'decree');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('veto-1', 'veto', 'The president used his veto to stop the bill from becoming law.', '总统行使否决权,阻止这项法案成为法律。', 'veto');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ultimatum-1', 'ultimatum', 'The union gave the company an ultimatum over pay and working hours.', '工会就工资和工时向公司发出了最后通牒。', 'ultimatum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dictatorial-1', 'dictatorial', 'A dictatorial government does not allow people to criticise its decisions.', '独裁政府不允许人们批评它的决定。', 'dictatorial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('authoritative-1', 'authoritative', 'People need authoritative sources of information during a health crisis.', '在健康危机期间,人们需要权威的信息来源。', 'authoritative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('centralise-1', 'centralise', 'Some governments centralise power, leaving local leaders with little control.', '一些政府把权力集中起来,使地方领导人几乎没有控制权。', 'centralise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('govern-1', 'govern', 'Leaders who govern fairly tend to win the trust of their people.', '公正治理的领导人往往能赢得人民的信任。', 'govern');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('administer-1', 'administer', 'The money is administered by a committee of local residents.', '这笔钱由当地居民组成的委员会管理。', 'administered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confer-1', 'confer', 'A university degree may confer certain advantages in the job market.', '大学学位可能在就业市场上带来某些优势。', 'confer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entitle-1', 'entitle', 'A valid student card will entitle you to reduced prices on transport.', '有效的学生证使你有权享受交通优惠。', 'entitle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('empower-1', 'empower', 'Education can empower women to make their own decisions.', '教育能使女性有能力自己作决定。', 'empower');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deport-1', 'deport', 'The government has the power to deport foreign criminals after they serve their sentences.', '政府有权在外国罪犯服刑后将其驱逐出境。', 'deport');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('armament-1', 'armament', 'Too much public money is spent on armament rather than on schools.', '太多公共资金花在军备上,而不是学校上。', 'armament');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disarm-1', 'disarm', 'Many countries have agreed to disarm in order to reduce the risk of war.', '许多国家同意裁军,以减少战争风险。', 'disarm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('naval-1', 'naval', 'The country''s naval forces protect ships from attack in international waters.', '该国海军力量保护船只在国际水域免受袭击。', 'naval');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tactics-1', 'tactics', 'The police changed their tactics after criticism of the way they treated protesters.', '警方因对待抗议者的方式受到批评,改变了策略。', 'tactics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('morale-1', 'morale', 'Low pay and long hours have damaged morale among nurses.', '低工资和长工时损害了护士的士气。', 'morale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raid-1', 'raid', 'Police arrested three men during a raid on the warehouse.', '警方在突袭仓库时逮捕了三名男子。', 'raid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encroach-1', 'encroach', 'New housing developments continue to encroach on valuable farmland.', '新的住房开发项目继续侵占宝贵的农田。', 'encroach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confidential-1', 'confidential', 'Medical records are confidential and should be protected by law.', '病历是机密的,应受到法律保护。', 'confidential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clandestine-1', 'clandestine', 'The group held clandestine meetings to plan their campaign against the government.', '这个团体秘密开会,策划反政府运动。', 'clandestine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assembly-1', 'assembly', 'The national assembly voted to raise the school-leaving age.', '国民议会投票决定提高离校年龄。', 'assembly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alliance-1', 'alliance', 'The two nations formed an alliance to protect their trade routes.', '两国结成联盟,保护贸易路线。', 'alliance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('missile-1', 'missile', 'The development of a single missile can cost hundreds of millions of dollars.', '研发一枚导弹可能花费数亿美元。', 'missile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consultation-1', 'consultation', 'The new rules were introduced without consultation with local residents.', '新规定在没有与当地居民磋商的情况下出台了。', 'consultation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('directive-1', 'directive', 'A new directive requires all member states to reduce their waste.', '一项新指令要求所有成员国减少废物。', 'directive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incumbent-1', 'incumbent', 'The incumbent lost the election because of rising unemployment.', '由于失业率上升,现任者输掉了选举。', 'incumbent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coalition-1', 'coalition', 'The two parties formed a coalition after neither won a majority.', '两党都未获得多数席位,于是组成了联合政府。', 'coalition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('federation-1', 'federation', 'The country is a federation of several largely independent states.', '这个国家是由几个基本独立的州组成的联邦。', 'federation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chancellor-1', 'chancellor', 'The chancellor announced an increase in spending on schools and hospitals.', '财政大臣宣布增加对学校和医院的支出。', 'chancellor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ambassador-1', 'ambassador', 'The ambassador met local business leaders to discuss trade between the countries.', '大使会见了当地商界领袖,讨论两国贸易。', 'ambassador');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embassy-1', 'embassy', 'Visitors must apply for a visa at the embassy before they travel.', '游客出行前必须到大使馆申请签证。', 'embassy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protest-1', 'protest', 'Thousands of students joined the protest against higher university fees.', '数千名学生参加了反对提高大学学费的抗议。', 'protest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protest-2', 'protest', 'Local people protested against the plan to close the village school.', '当地人抗议关闭村校的计划。', 'protested');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rally-1', 'rally', 'Thousands of people attended a rally to support the striking workers.', '数千人参加集会,支持罢工工人。', 'rally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petition-1', 'petition', 'More than ten thousand people signed a petition against the new airport.', '一万多人在反对新机场的请愿书上签了名。', 'petition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unrest-1', 'unrest', 'High unemployment among young people can lead to social unrest.', '年轻人失业率高可能导致社会动荡。', 'unrest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turmoil-1', 'turmoil', 'The sudden fall in share prices caused turmoil in world markets.', '股价突然下跌造成了世界市场的混乱。', 'turmoil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('partisan-1', 'partisan', 'Partisan debate makes it difficult to reach agreement on important issues.', '党派争论使重要问题难以达成一致。', 'Partisan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ally-1', 'ally', 'The country relied heavily on its closest ally for protection.', '这个国家严重依赖最亲密的盟友提供保护。', 'ally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nominee-1', 'nominee', 'The president''s nominee for the highest court was approved last week.', '总统提名的最高法院人选上周获得批准。', 'nominee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nominate-1', 'nominate', 'Each party will nominate one candidate to stand for election.', '每个政党将提名一名候选人参加竞选。', 'nominate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('asylum-1', 'asylum', 'Many people seek asylum in order to escape war in their own countries.', '许多人寻求庇护,以逃离本国的战争。', 'asylum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conspiracy-1', 'conspiracy', 'Many people still believe the conspiracy theories that spread on social media.', '许多人仍然相信社交媒体上流传的阴谋论。', 'conspiracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('militant-1', 'militant', 'Militant groups have attacked government buildings in the north of the country.', '好战团体袭击了该国北部的政府建筑。', 'Militant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bilateral-1', 'bilateral', 'The two countries signed a bilateral agreement on trade and education.', '两国签署了一项关于贸易和教育的双边协议。', 'bilateral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('criminal-1', 'criminal', 'A convicted criminal may find it very difficult to get a job.', '被定罪的罪犯可能很难找到工作。', 'criminal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('criminal-2', 'criminal', 'Criminal behaviour among young people is often linked to poverty.', '年轻人的犯罪行为常常与贫困有关。', 'Criminal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offender-1', 'offender', 'A young offender should receive education as well as punishment.', '青少年罪犯在接受惩罚的同时也应接受教育。', 'offender');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offence-1', 'offence', 'Driving while using a mobile phone is a serious offence.', '开车时使用手机是一种严重的违法行为。', 'offence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('juvenile-delinquency-1', 'juvenile-delinquency', 'Lack of parental guidance is often seen as a cause of juvenile delinquency.', '缺乏父母指导常被视为青少年犯罪的一个原因。', 'juvenile delinquency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('violent-crime-1', 'violent-crime', 'Violent crime is more common in areas with high unemployment.', '暴力犯罪在失业率高的地区更为常见。', 'Violent crime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('theft-1', 'theft', 'Mobile phone theft has become a common problem in large cities.', '手机盗窃已成为大城市的常见问题。', 'theft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burglary-1', 'burglary', 'Good street lighting can help to reduce burglary in residential areas.', '良好的街道照明有助于减少住宅区的入室盗窃。', 'burglary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('robbery-1', 'robbery', 'The man was sent to prison for his part in a bank robbery.', '这名男子因参与银行抢劫被送进监狱。', 'robbery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fraud-1', 'fraud', 'Online fraud costs consumers millions of pounds every year.', '网络欺诈每年使消费者损失数百万英镑。', 'fraud');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('murder-1', 'murder', 'Some people believe that murder should be punished with life in prison.', '有些人认为谋杀应被判处终身监禁。', 'murder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assault-1', 'assault', 'He received a two-year sentence for assault on a police officer.', '他因袭击警察被判处两年徒刑。', 'assault');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vandalism-1', 'vandalism', 'Young people with nothing to do may turn to vandalism.', '无所事事的年轻人可能转向故意破坏公物。', 'vandalism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('smuggling-1', 'smuggling', 'Tighter border controls have reduced the smuggling of goods.', '更严格的边境管制减少了货物走私。', 'smuggling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drug-trafficking-1', 'drug-trafficking', 'Drug trafficking is a serious crime that carries a long prison sentence.', '贩毒是严重的犯罪,会被判处长期徒刑。', 'Drug trafficking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legal-1', 'legal', 'People under the legal age should not be allowed to buy alcohol.', '未达到合法年龄的人不应被允许购买酒精饮料。', 'legal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illegal-1', 'illegal', 'It is illegal to sell cigarettes to children in most countries.', '在大多数国家,向儿童出售香烟是非法的。', 'illegal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lawyer-1', 'lawyer', 'Everyone accused of a crime should have the right to a lawyer.', '每个被指控犯罪的人都应有权聘请律师。', 'lawyer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solicitor-1', 'solicitor', 'You should ask a solicitor for advice before signing the contract.', '签合同之前,你应该咨询律师。', 'solicitor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attorney-1', 'attorney', 'The attorney argued that the evidence against his client was not reliable.', '律师辩称,对他当事人不利的证据并不可靠。', 'attorney');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('judge-1', 'judge', 'The judge decided that the company had broken the law.', '法官判定这家公司违反了法律。', 'judge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jury-1', 'jury', 'The jury found the man guilty after three days of discussion.', '陪审团经过三天讨论,认定该男子有罪。', 'jury');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('court-1', 'court', 'The case will be heard in court at the end of next month.', '这个案件将于下月底在法院审理。', 'court');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sue-1', 'sue', 'Customers may sue a company if its products cause them harm.', '如果产品对顾客造成伤害,顾客可以起诉公司。', 'sue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prosecute-1', 'prosecute', 'The police decided not to prosecute the driver because of a lack of evidence.', '由于证据不足,警方决定不起诉这名司机。', 'prosecute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defendant-1', 'defendant', 'The defendant said that he had been at home when the crime took place.', '被告称案发时他在家。', 'defendant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plaintiff-1', 'plaintiff', 'The plaintiff claimed that the company had failed to protect its workers.', '原告称公司未能保护其员工。', 'plaintiff');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('witness-1', 'witness', 'A witness told the court that she had seen the man leave the shop.', '一名证人告诉法庭,她看到该男子离开了商店。', 'witness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('verdict-1', 'verdict', 'The verdict surprised many people who had followed the case closely.', '这项判决令许多密切关注此案的人感到意外。', 'verdict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guilty-1', 'guilty', 'A person is considered innocent until proven guilty in a court of law.', '一个人在法庭证明有罪之前都被视为无罪。', 'guilty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('innocent-1', 'innocent', 'Some innocent people have spent years in prison for crimes they did not commit.', '一些无辜的人因未曾犯下的罪行在狱中度过多年。', 'innocent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convict-1', 'convict', 'The court needs clear evidence to convict someone of a serious crime.', '法院需要明确的证据才能判定某人犯有重罪。', 'convict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sentence-1', 'sentence', 'The judge gave the man a sentence of three years in prison.', '法官判处该男子三年监禁。', 'sentence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sentence-2', 'sentence', 'Young offenders should not be sentenced to long periods in adult prisons.', '青少年罪犯不应被判处在成人监狱长期服刑。', 'sentenced');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('penalty-1', 'penalty', 'There should be a heavier penalty for driving after drinking alcohol.', '酒后驾车应受到更重的惩罚。', 'penalty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('death-penalty-1', 'death-penalty', 'Many countries have abolished the death penalty in recent decades.', '近几十年来,许多国家废除了死刑。', 'death penalty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capital-punishment-1', 'capital-punishment', 'Supporters of capital punishment argue that it prevents serious crime.', '死刑的支持者认为它能防止严重犯罪。', 'capital punishment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imprisonment-1', 'imprisonment', 'Long periods of imprisonment do not always reduce the rate of crime.', '长期监禁并不总能降低犯罪率。', 'imprisonment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prison-1', 'prison', 'Sending young people to prison may make them more likely to reoffend.', '把年轻人送进监狱可能使他们更容易再次犯罪。', 'prison');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jail-1', 'jail', 'He spent five years in jail for stealing from the company.', '他因盗窃公司财物坐了五年牢。', 'jail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prisoner-1', 'prisoner', 'Every prisoner should have the chance to learn new skills for life after release.', '每个囚犯都应有机会学习新技能,为出狱后的生活做准备。', 'prisoner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inmate-1', 'inmate', 'Each inmate in the prison is offered basic education and job training.', '监狱里的每个囚犯都能接受基础教育和职业培训。', 'inmate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parole-1', 'parole', 'He was released on parole after serving half of his sentence.', '他服完一半刑期后获得假释。', 'parole');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('community-service-1', 'community-service', 'Community service may be better than prison for people who commit minor crimes.', '对于轻微犯罪者,社区服务可能比监禁更好。', 'Community service');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deter-1', 'deter', 'Tougher punishments may deter young people from committing crime.', '更严厉的惩罚可能阻止年轻人犯罪。', 'deter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deterrent-1', 'deterrent', 'Some people believe that long prison sentences act as a deterrent.', '有些人认为长期徒刑能起到威慑作用。', 'deterrent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rehabilitate-1', 'rehabilitate', 'Prisons should try to rehabilitate offenders rather than simply punish them.', '监狱应该努力改造罪犯,而不只是惩罚他们。', 'rehabilitate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reoffend-1', 'reoffend', 'Prisoners who gain new skills are less likely to reoffend after release.', '掌握新技能的囚犯出狱后不太可能再次犯罪。', 'reoffend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patrol-1', 'patrol', 'More officers should patrol the streets on foot to make residents feel safe.', '应该有更多警察步行巡逻街道,让居民感到安全。', 'patrol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arrest-1', 'arrest', 'The police made an arrest within two days of the crime.', '案发两天内,警方就实施了逮捕。', 'arrest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('investigation-1', 'investigation', 'A police investigation found that the fire had been started deliberately.', '警方调查发现这场火灾是人为纵火。', 'investigation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspect-1', 'suspect', 'Police have questioned a suspect in connection with the robbery.', '警方已就这起抢劫案询问了一名嫌疑人。', 'suspect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspect-2', 'suspect', 'Many experts suspect that the real figures are far higher.', '许多专家怀疑实际数字要高得多。', 'suspect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('victim-1', 'victim', 'The victim of a crime often needs emotional as well as practical support.', '犯罪受害者往往既需要实际帮助,也需要情感支持。', 'victim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('justice-1', 'justice', 'Everyone should have equal access to justice, whatever their income.', '无论收入如何,每个人都应平等地获得司法保障。', 'justice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comply-with-1', 'comply-with', 'Companies that fail to comply with safety laws should face heavy fines.', '不遵守安全法规的公司应当面临高额罚款。', 'comply with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('violate-1', 'violate', 'Companies that violate environmental rules should be forced to pay for the damage.', '违反环境法规的公司应被迫赔偿损失。', 'violate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('law-abiding-1', 'law-abiding', 'Most law-abiding citizens support stronger action against serious crime.', '大多数守法公民支持加强打击严重犯罪。', 'law-abiding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constitution-1', 'constitution', 'The country''s constitution guarantees freedom of speech to all citizens.', '该国宪法保障所有公民的言论自由。', 'constitution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clause-1', 'clause', 'A clause in the contract allows the company to end the agreement early.', '合同中的一项条款允许公司提前终止协议。', 'clause');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enact-1', 'enact', 'The government plans to enact a new law on data protection.', '政府计划制定一项关于数据保护的新法律。', 'enact');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legalise-1', 'legalise', 'Some countries have decided to legalise the use of cannabis for medical purposes.', '一些国家决定把医用大麻合法化。', 'legalise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abolish-1', 'abolish', 'Some people believe that governments should abolish all school fees.', '有些人认为政府应该废除所有学费。', 'abolish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invalidate-1', 'invalidate', 'Any change to the document may invalidate the entire agreement.', '对文件的任何改动都可能使整个协议无效。', 'invalidate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mandatory-1', 'mandatory', 'Wearing a seat belt is mandatory for all passengers in the car.', '车内所有乘客都必须系安全带。', 'mandatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obligatory-1', 'obligatory', 'Military service is no longer obligatory in many European countries.', '在许多欧洲国家,服兵役已不再是义务。', 'obligatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('licensed-1', 'licensed', 'Only licensed doctors should be allowed to prescribe these drugs.', '只有获得许可的医生才能开这些药。', 'licensed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forbid-1', 'forbid', 'Some countries forbid the use of mobile phones in schools.', '一些国家禁止在学校使用手机。', 'forbid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obey-1', 'obey', 'Children who learn to obey rules at home tend to behave better at school.', '在家学会遵守规矩的孩子在学校往往表现更好。', 'obey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accuse-1', 'accuse', 'Critics accuse the government of ignoring the needs of rural communities.', '批评者指控政府忽视农村社区的需求。', 'accuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accusation-1', 'accusation', 'The minister has denied the accusation that he misused public money.', '这位部长否认了他滥用公共资金的指控。', 'accusation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lawsuit-1', 'lawsuit', 'Several families filed a lawsuit against the company over the polluted water.', '几个家庭就水污染问题对该公司提起诉讼。', 'lawsuit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indictment-1', 'indictment', 'The high rate of youth unemployment is an indictment of government policy.', '青年失业率高是对政府政策的控诉。', 'indictment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impeach-1', 'impeach', 'Parliament voted to impeach the president after the corruption scandal.', '腐败丑闻发生后,议会投票决定弹劾总统。', 'impeach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('testify-1', 'testify', 'Witnesses must testify in court if they are asked to do so.', '如果被要求,证人必须出庭作证。', 'testify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('testimony-1', 'testimony', 'Her testimony helped the jury to reach its final decision.', '她的证词帮助陪审团作出了最终决定。', 'testimony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plead-1', 'plead', 'The man decided to plead guilty in the hope of a shorter sentence.', '该男子决定认罪,希望获得较短的刑期。', 'plead');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defend-1', 'defend', 'The lawyer agreed to defend the young man in court for free.', '律师同意在法庭上免费为这名年轻人辩护。', 'defend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acquit-1', 'acquit', 'The jury decided to acquit the woman because the evidence was weak.', '由于证据不足,陪审团决定宣判这名女子无罪。', 'acquit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arbitration-1', 'arbitration', 'The two sides agreed to settle their dispute through arbitration.', '双方同意通过仲裁解决争端。', 'arbitration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confiscate-1', 'confiscate', 'Schools have the right to confiscate phones used during lessons.', '学校有权没收上课时使用的手机。', 'confiscate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detain-1', 'detain', 'Police can detain a suspect for up to twenty-four hours without charge.', '警方可以在不起诉的情况下拘留嫌疑人最多二十四小时。', 'detain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interrogate-1', 'interrogate', 'Officers are not allowed to interrogate children without an adult present.', '没有成年人在场,警察不得审问儿童。', 'interrogate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oath-1', 'oath', 'Doctors take an oath to protect the health of their patients.', '医生宣誓保护患者的健康。', 'oath');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pledge-1', 'pledge', 'The government made a pledge to reduce carbon emissions by half.', '政府承诺把碳排放量减少一半。', 'pledge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heir-1', 'heir', 'The heir to the family''s fortune chose to give most of it away.', '这个家族财富的继承人选择把大部分捐出去。', 'heir');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indemnity-1', 'indemnity', 'The company paid an indemnity to the workers who were injured.', '公司向受伤工人支付了赔偿。', 'indemnity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impunity-1', 'impunity', 'Large companies should not be able to pollute rivers with impunity.', '大公司不应污染河流而不受惩罚。', 'impunity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exempt-1', 'exempt', 'Small businesses are exempt from the new tax on waste.', '小企业免缴新的垃圾税。', 'exempt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('condone-1', 'condone', 'Society should never condone violence against children in any form.', '社会绝不应纵容任何形式的针对儿童的暴力。', 'condone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('condemn-1', 'condemn', 'World leaders were quick to condemn the attack on the hospital.', '世界各国领导人迅速谴责了对医院的袭击。', 'condemn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('denounce-1', 'denounce', 'Human rights groups denounced the arrest of the journalists.', '人权组织公开谴责了逮捕记者的行为。', 'denounced');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('complaint-1', 'complaint', 'The company received thousands of complaints about its poor service.', '这家公司收到了数千份关于服务差的投诉。', 'complaints');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offensive-1', 'offensive', 'Comments that are offensive to others should be removed from social media.', '冒犯他人的评论应从社交媒体上删除。', 'offensive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('liberate-1', 'liberate', 'Education can liberate people from poverty and limited opportunities.', '教育能把人们从贫困和有限的机会中解放出来。', 'liberate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('release-1', 'release', 'Prisoners need support in finding work after their release.', '囚犯出狱后找工作需要帮助。', 'release');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('release-2', 'release', 'The government will release the full results of the survey next month.', '政府将在下个月发布调查的全部结果。', 'release');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flee-1', 'flee', 'Millions of people have been forced to flee their homes because of war.', '数百万人因战争被迫逃离家园。', 'flee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('penal-1', 'penal', 'The country''s penal system should focus more on education and training.', '该国的刑罚制度应该更加注重教育和培训。', 'penal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illicit-1', 'illicit', 'The illicit trade in wild animals threatens many rare species.', '非法的野生动物贸易威胁着许多珍稀物种。', 'illicit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illegitimate-1', 'illegitimate', 'Protesters claimed that the new government was illegitimate after a false election.', '抗议者称,虚假选举后产生的新政府是非法的。', 'illegitimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wilful-1', 'wilful', 'The company was fined for the wilful destruction of the forest.', '这家公司因故意破坏森林被罚款。', 'wilful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heinous-1', 'heinous', 'Those who commit heinous crimes should face the strictest punishment.', '犯下极其恶劣罪行的人应受到最严厉的惩罚。', 'heinous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('counterfeit-1', 'counterfeit', 'Counterfeit medicines are a serious danger to people in many poor countries.', '伪造药品对许多贫穷国家的人构成严重危险。', 'Counterfeit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blackmail-1', 'blackmail', 'Criminals used stolen photographs to blackmail people on social media.', '犯罪分子利用盗取的照片在社交媒体上敲诈他人。', 'blackmail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ransom-1', 'ransom', 'Hackers locked the hospital''s computers and demanded a ransom.', '黑客锁定了医院的电脑,并索要赎金。', 'ransom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pickpocket-1', 'pickpocket', 'A pickpocket can quickly steal a wallet in a crowded tourist area.', '在拥挤的旅游区,扒手能迅速偷走钱包。', 'pickpocket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arson-1', 'arson', 'Investigators believe that the fire at the school was a case of arson.', '调查人员认为学校的火灾是一起纵火案。', 'arson');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rape-1', 'rape', 'Victims of rape often need long-term support as well as legal help.', '强奸受害者不仅需要法律帮助,往往还需要长期支持。', 'rape');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instigate-1', 'instigate', 'Some social media users try to instigate violence during public protests.', '一些社交媒体用户试图在公众抗议期间煽动暴力。', 'instigate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lure-1', 'lure', 'Criminals use false job offers to lure young people abroad.', '犯罪分子用虚假的工作机会诱骗年轻人出国。', 'lure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abuse-1', 'abuse', 'Children who suffer abuse may have problems with relationships as adults.', '遭受虐待的孩子成年后可能在人际关系上出现问题。', 'abuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abuse-2', 'abuse', 'Some officials abuse their power to gain money for themselves.', '一些官员滥用权力为自己谋取钱财。', 'abuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hostility-1', 'hostility', 'Immigrants may face hostility in areas with high unemployment.', '在失业率高的地区,移民可能面临敌意。', 'hostility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('riot-1', 'riot', 'A riot broke out in the city after the announcement of the new tax.', '新税公布后,这座城市爆发了暴乱。', 'riot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recidivism-1', 'recidivism', 'Education in prison can greatly reduce recidivism among young offenders.', '狱中教育可以大大减少青少年罪犯的累犯率。', 'recidivism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commit-a-crime-1', 'commit-a-crime', 'Young people who commit a crime should not automatically go to prison.', '犯罪的年轻人不应该自动被送进监狱。', 'commit a crime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('break-the-law-1', 'break-the-law', 'Companies that break the law should pay heavy fines.', '违法的公司应该支付高额罚款。', 'break the law');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('law-enforcement-1', 'law-enforcement', 'Law enforcement agencies are working together to stop online crime.', '执法机构正在合作打击网络犯罪。', 'Law enforcement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('organised-crime-1', 'organised-crime', 'Organised crime often grows in places where the government is weak.', '有组织犯罪往往在政府薄弱的地方滋生。', 'Organised crime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tax-evasion-1', 'tax-evasion', 'Tax evasion costs governments billions of pounds in lost money every year.', '逃税每年使各国政府损失数十亿英镑。', 'Tax evasion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('child-abuse-1', 'child-abuse', 'Teachers are trained to recognise the signs of child abuse.', '教师接受培训,学习识别虐待儿童的迹象。', 'child abuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('death-sentence-1', 'death-sentence', 'The court''s death sentence caused anger among human rights groups.', '法院的死刑判决引起了人权组织的愤怒。', 'death sentence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consent-1', 'consent', 'Doctors must obtain a patient''s consent before any operation.', '医生必须在任何手术前征得患者的同意。', 'consent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consent-2', 'consent', 'Parents must consent before their children can join the school trip.', '孩子参加学校旅行前,必须得到父母的同意。', 'consent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bullet-1', 'bullet', 'The bullet missed the police officer and hit a car parked nearby.', '子弹没有击中警察,而是打中了停在附近的一辆车。', 'bullet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legitimate-1', 'legitimate', 'Criticising the government is a legitimate right in a free society.', '在自由社会,批评政府是一项合法的权利。', 'legitimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('liable-1', 'liable', 'Companies are liable for any injuries caused by their faulty products.', '公司要为其缺陷产品造成的任何伤害负法律责任。', 'liable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thief-1', 'thief', 'The thief was caught after a camera recorded his face.', '摄像头拍到了小偷的脸,他随后被抓获。', 'thief');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gang-1', 'gang', 'Teenagers without jobs may be persuaded to join a criminal gang.', '没有工作的青少年可能被说服加入犯罪团伙。', 'gang');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('killer-1', 'killer', 'Heart disease remains the biggest killer in most developed countries.', '在大多数发达国家,心脏病仍然是头号杀手。', 'killer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breach-1', 'breach', 'The company''s use of personal data was a clear breach of the law.', '该公司使用个人数据的做法明显违反了法律。', 'breach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('negligence-1', 'negligence', 'The hospital was found guilty of negligence after the patient''s death.', '患者死亡后,医院被判定有疏忽之责。', 'negligence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magistrate-1', 'magistrate', 'The magistrate ordered the young man to pay a small fine.', '地方法官判令这名年轻人支付一小笔罚款。', 'magistrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hostage-1', 'hostage', 'The police managed to free the hostage after several hours of discussions.', '经过几小时的谈判,警方成功解救了人质。', 'hostage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kidnap-1', 'kidnap', 'The gang tried to kidnap the businessman for a large sum of money.', '这个团伙试图绑架这名商人,以索取巨款。', 'kidnap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harassment-1', 'harassment', 'Companies should have clear rules to deal with harassment at work.', '公司应该有明确的规定来处理工作中的骚扰。', 'harassment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('judicial-1', 'judicial', 'An independent judicial system is essential for a fair society.', '独立的司法体系对公平的社会至关重要。', 'judicial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cocaine-1', 'cocaine', 'Police found a large amount of cocaine hidden in the ship.', '警方在船上发现了大量隐藏的可卡因。', 'cocaine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('environment-1', 'environment', 'Everyone has a duty to protect the environment for future generations.', '每个人都有责任为子孙后代保护环境。', 'environment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('environmental-1', 'environmental', 'Environmental problems cannot be solved by any one country alone.', '环境问题不是任何一个国家能单独解决的。', 'Environmental');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollution-1', 'pollution', 'Pollution from factories is damaging rivers and lakes across the region.', '工厂造成的污染正在破坏该地区的河流和湖泊。', 'Pollution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollutant-1', 'pollutant', 'Factories should be required to reduce the pollutants they release into rivers.', '应要求工厂减少排入河流的污染物。', 'pollutants');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contaminate-1', 'contaminate', 'Chemicals used on farms can contaminate drinking water supplies.', '农场使用的化学品可能污染饮用水源。', 'contaminate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('air-pollution-1', 'air-pollution', 'Air pollution is a major cause of breathing problems in large cities.', '空气污染是大城市呼吸问题的主要原因。', 'Air pollution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('water-pollution-1', 'water-pollution', 'Water pollution from mines has killed most of the fish in the river.', '矿山造成的水污染杀死了河里的大部分鱼。', 'Water pollution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('noise-pollution-1', 'noise-pollution', 'Noise pollution from aircraft can damage the health of nearby residents.', '飞机造成的噪音污染可能损害附近居民的健康。', 'Noise pollution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('light-pollution-1', 'light-pollution', 'Light pollution in cities makes it difficult to see the stars at night.', '城市的光污染使人们夜间很难看到星星。', 'Light pollution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('smog-1', 'smog', 'Thick smog forced the government to close schools for several days.', '浓重的雾霾迫使政府关闭学校数日。', 'smog');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhaust-1', 'exhaust', 'Exhaust from cars is one of the main sources of air pollution.', '汽车尾气是空气污染的主要来源之一。', 'Exhaust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhaust-2', 'exhaust', 'Humans may exhaust the planet''s supplies of oil within this century.', '人类可能在本世纪内耗尽地球的石油储量。', 'exhaust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fumes-1', 'fumes', 'Traffic fumes are particularly harmful to young children walking to school.', '交通废气对步行上学的幼儿尤其有害。', 'fumes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waste-1', 'waste', 'Most household waste could be recycled if people sorted it properly.', '如果人们正确分类,大部分生活垃圾都可以回收。', 'waste');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waste-2', 'waste', 'Many people waste water by leaving taps running while they brush their teeth.', '许多人刷牙时不关水龙头,浪费了水。', 'waste');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landfill-1', 'landfill', 'Most of the city''s rubbish still goes to landfill outside the town.', '这座城市的大部分垃圾仍被送往城外的垃圾填埋场。', 'landfill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incineration-1', 'incineration', 'Incineration reduces the amount of waste but can release harmful gases.', '焚化能减少废物量,但可能释放有害气体。', 'Incineration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rubbish-1', 'rubbish', 'People should be fined for leaving rubbish on the beach.', '在海滩上留下垃圾的人应该被罚款。', 'rubbish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('litter-1', 'litter', 'Litter in the streets makes a city look dirty and uncared for.', '街道上的垃圾使城市看起来又脏又没人管。', 'Litter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('litter-2', 'litter', 'People who litter in public parks should be made to pay a fine.', '在公园乱扔垃圾的人应该被罚款。', 'litter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disposable-1', 'disposable', 'Disposable products create huge amounts of waste that do not break down.', '一次性产品产生大量无法分解的废物。', 'Disposable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plastic-bag-1', 'plastic-bag', 'A single plastic bag can take hundreds of years to break down.', '一个塑料袋可能需要数百年才能分解。', 'plastic bag');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('packaging-1', 'packaging', 'Supermarkets should reduce the amount of packaging used on their food.', '超市应该减少食品的包装用量。', 'packaging');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biodegradable-1', 'biodegradable', 'Biodegradable materials could replace much of the plastic used today.', '可生物降解材料可以取代今天使用的大部分塑料。', 'Biodegradable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recycling-1', 'recycling', 'Recycling should be compulsory for all homes and businesses.', '所有家庭和企业都应强制进行回收。', 'Recycling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reuse-1', 'reuse', 'Families should reuse glass bottles rather than throw them away.', '家庭应该重复使用玻璃瓶,而不是扔掉。', 'reuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-footprint-1', 'carbon-footprint', 'Eating less meat is an easy way to reduce your carbon footprint.', '少吃肉是减少碳足迹的简单方法。', 'carbon footprint');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-neutral-1', 'carbon-neutral', 'The city aims to become carbon neutral within the next twenty years.', '这座城市的目标是在未来二十年内实现碳中和。', 'carbon neutral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('low-carbon-1', 'low-carbon', 'Governments should encourage a low-carbon economy through taxes and subsidies.', '政府应该通过税收和补贴鼓励低碳经济。', 'low-carbon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eco-friendly-1', 'eco-friendly', 'More consumers are willing to pay extra for eco-friendly products.', '越来越多的消费者愿意为环保产品多付钱。', 'eco-friendly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('green-1', 'green', 'Green policies should be at the centre of every government''s plans.', '环保政策应该成为每个政府计划的核心。', 'Green');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clean-energy-1', 'clean-energy', 'Investing in clean energy would create jobs and reduce air pollution.', '投资清洁能源既能创造就业机会,又能减少空气污染。', 'clean energy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alternative-energy-1', 'alternative-energy', 'Investment in alternative energy would reduce our dependence on fossil fuels.', '投资替代能源将减少我们对化石燃料的依赖。', 'alternative energy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('energy-efficient-1', 'energy-efficient', 'New homes should be energy-efficient in order to reduce household bills.', '新房应该节能,以减少家庭开支。', 'energy-efficient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resource-1', 'resource', 'Water is a precious resource that should not be wasted.', '水是一种宝贵的资源,不应被浪费。', 'resource');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('natural-resources-1', 'natural-resources', 'Developed countries consume far more than their fair share of natural resources.', '发达国家消耗的自然资源远远超过了它们应得的份额。', 'natural resources');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('finite-1', 'finite', 'Oil is a finite resource that will eventually run out.', '石油是一种有限的资源,最终会用完。', 'finite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depletion-1', 'depletion', 'The depletion of fish stocks threatens the jobs of many coastal communities.', '鱼类资源的枯竭威胁着许多沿海社区的就业。', 'depletion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deplete-1', 'deplete', 'Modern farming methods can deplete the soil of its natural nutrients.', '现代耕作方法可能耗尽土壤的天然养分。', 'deplete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scarcity-1', 'scarcity', 'Water scarcity is likely to become a major cause of international conflict.', '缺水可能成为国际冲突的主要原因。', 'scarcity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shortage-1', 'shortage', 'A shortage of affordable housing is forcing young people out of the city.', '经济适用房的短缺正把年轻人赶出城市。', 'shortage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ecological-balance-1', 'ecological-balance', 'Removing a single species can upset the ecological balance of an area.', '移除单个物种可能破坏一个地区的生态平衡。', 'ecological balance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('degradation-1', 'degradation', 'Environmental degradation can have serious effects on human health.', '环境退化可能严重影响人类健康。', 'degradation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('desertification-1', 'desertification', 'Overgrazing and climate change are the main causes of desertification.', '过度放牧和气候变化是荒漠化的主要原因。', 'desertification');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soil-erosion-1', 'soil-erosion', 'Cutting down trees on hillsides can lead to serious soil erosion.', '砍伐山坡上的树木可能导致严重的水土流失。', 'soil erosion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acid-rain-1', 'acid-rain', 'Acid rain has damaged forests and lakes across northern Europe.', '酸雨破坏了北欧各地的森林和湖泊。', 'Acid rain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('climate-change-1', 'climate-change', 'Climate change is the most serious environmental problem facing the world.', '气候变化是世界面临的最严重的环境问题。', 'Climate change');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('natural-disaster-1', 'natural-disaster', 'Poor countries are often the worst affected by a natural disaster.', '贫穷国家往往受自然灾害的影响最严重。', 'natural disaster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catastrophe-1', 'catastrophe', 'Scientists warn of a catastrophe if the ice sheets continue to melt.', '科学家警告,如果冰盖继续融化,将发生灾难。', 'catastrophe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irreversible-1', 'irreversible', 'The damage to the world''s coral reefs may already be irreversible.', '世界珊瑚礁所受的损害可能已经不可逆转。', 'irreversible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preservation-1', 'preservation', 'The preservation of old forests should be a priority for every government.', '保护古老森林应该是每个政府的优先事项。', 'preservation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('environmentalist-1', 'environmentalist', 'An environmentalist would argue that economic growth is not always a good thing.', '环保主义者会认为经济增长并不总是好事。', 'environmentalist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wildlife-reserve-1', 'wildlife-reserve', 'A wildlife reserve gives rare animals a safe place to live and breed.', '野生动物保护区为珍稀动物提供了安全的生活和繁殖场所。', 'wildlife reserve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('national-park-1', 'national-park', 'Visitor numbers to the national park should be limited to protect wildlife.', '应该限制国家公园的游客数量,以保护野生动物。', 'national park');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollute-1', 'pollute', 'Factories that pollute rivers should have to pay for the clean-up.', '污染河流的工厂应该支付清理费用。', 'pollute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('polluted-1', 'polluted', 'Children living in polluted cities are more likely to suffer from asthma.', '生活在污染城市的孩子更容易患哮喘。', 'polluted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contamination-1', 'contamination', 'Contamination of food can lead to serious illness among consumers.', '食品污染可能导致消费者患上严重疾病。', 'Contamination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contaminated-1', 'contaminated', 'Drinking contaminated water is a major cause of death in poor countries.', '饮用受污染的水是贫穷国家的主要死因。', 'contaminated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('poisonous-1', 'poisonous', 'Burning plastic releases poisonous gases into the air.', '焚烧塑料会向空气中释放有毒气体。', 'poisonous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('noxious-1', 'noxious', 'Noxious gases from the factory have damaged the health of local people.', '工厂排出的有害气体损害了当地人的健康。', 'Noxious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discharge-1', 'discharge', 'Factories must not discharge untreated waste into local rivers.', '工厂不得向当地河流排放未经处理的废物。', 'discharge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sewerage-1', 'sewerage', 'Many poor neighbourhoods still have no proper sewerage system.', '许多贫困社区仍然没有完善的排污系统。', 'sewerage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decibel-1', 'decibel', 'Noise above eighty-five decibels can damage people''s hearing over time.', '超过八十五分贝的噪音长期下来会损害听力。', 'decibels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deterioration-1', 'deterioration', 'The deterioration of air quality is a serious concern in many large cities.', '空气质量恶化是许多大城市严重关切的问题。', 'deterioration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harm-1', 'harm', 'Most pesticides do more harm than good in the long term.', '从长远来看,大多数农药弊大于利。', 'harm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harm-2', 'harm', 'Light from buildings can harm birds that migrate at night.', '建筑物的灯光可能伤害夜间迁徙的鸟类。', 'harm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vivisection-1', 'vivisection', 'Some people believe vivisection is cruel and should be banned.', '有些人认为活体解剖很残忍,应该被禁止。', 'vivisection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sustainable-development-1', 'sustainable-development', 'Sustainable development meets present needs without harming future generations.', '可持续发展既满足当前需要,又不损害子孙后代。', 'Sustainable development');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-emissions-1', 'carbon-emissions', 'Taxes on air travel could help to reduce carbon emissions.', '对航空旅行征税有助于减少碳排放。', 'carbon emissions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('energy-consumption-1', 'energy-consumption', 'Better insulation would greatly reduce energy consumption in older homes.', '更好的隔热层将大大减少老房子的能源消耗。', 'energy consumption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waste-disposal-1', 'waste-disposal', 'Waste disposal is becoming a serious problem for fast-growing cities.', '废物处理正成为快速发展城市的严重问题。', 'Waste disposal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waste-water-1', 'waste-water', 'Waste water from the factory must be cleaned before it reaches the river.', '工厂废水流入河流前必须经过净化。', 'Waste water');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('water-shortage-1', 'water-shortage', 'Water shortage is already a serious problem in many dry regions.', '缺水已是许多干旱地区的严重问题。', 'Water shortage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wind-energy-1', 'wind-energy', 'Wind energy is now one of the cheapest sources of electricity.', '风能现在是最便宜的电力来源之一。', 'Wind energy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disaster-1', 'disaster', 'The oil spill was an environmental disaster for the whole coast.', '这次石油泄漏对整个海岸来说是一场环境灾难。', 'disaster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('survival-1', 'survival', 'The survival of many species depends on protecting their natural homes.', '许多物种的生存取决于保护它们的自然家园。', 'survival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('garbage-1', 'garbage', 'Garbage from cities is often shipped to poorer countries for disposal.', '城市垃圾常常被运到较贫穷的国家处理。', 'Garbage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dump-1', 'dump', 'Companies should not be allowed to dump chemical waste in the sea.', '不应允许公司向海里倾倒化学废物。', 'dump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dump-2', 'dump', 'The old rubbish dump outside the town has been turned into a park.', '镇外的旧垃圾场被改造成了公园。', 'dump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spill-1', 'spill', 'The oil spill killed thousands of sea birds along the coast.', '这次石油泄漏导致沿海数千只海鸟死亡。', 'spill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spill-2', 'spill', 'Tankers sometimes spill oil into the sea when they are damaged.', '油轮受损时有时会把石油泄漏到海里。', 'spill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evacuate-1', 'evacuate', 'Thousands of people had to evacuate their homes because of the flood.', '洪水迫使数千人疏散离家。', 'evacuate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('debris-1', 'debris', 'Plastic debris in the ocean kills large numbers of sea animals.', '海洋中的塑料碎片杀死了大量海洋动物。', 'debris');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('devastate-1', 'devastate', 'Rising sea levels could devastate low-lying countries such as Bangladesh.', '海平面上升可能摧毁孟加拉国等低洼国家。', 'devastate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wreck-1', 'wreck', 'Oil from the wreck spread along the coast for many miles.', '残骸漏出的石油沿海岸扩散了许多英里。', 'wreck');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('globalisation-1', 'globalisation', 'Globalisation has brought cheaper goods but has also destroyed some local jobs.', '全球化带来了更便宜的商品,但也使一些本地工作消失。', 'Globalisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('global-village-1', 'global-village', 'The internet has turned the world into a global village.', '互联网把世界变成了一个地球村。', 'global village');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('international-1', 'international', 'International cooperation is essential to solve the problem of climate change.', '要解决气候变化问题,国际合作至关重要。', 'International');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cross-cultural-1', 'cross-cultural', 'Cross-cultural experiences can help young people to become more tolerant.', '跨文化经历能帮助年轻人变得更加宽容。', 'Cross-cultural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multicultural-1', 'multicultural', 'Living in a multicultural society teaches people to respect different customs.', '生活在多元文化社会中,人们学会尊重不同的习俗。', 'multicultural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diversity-1', 'diversity', 'Cultural diversity makes a society richer and more interesting.', '文化多样性让社会更丰富、更有趣。', 'diversity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultural-identity-1', 'cultural-identity', 'Language is a central part of a nation''s cultural identity.', '语言是一个民族文化认同的核心部分。', 'cultural identity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tradition-1', 'tradition', 'Every society should try to keep its best traditions alive.', '每个社会都应该努力让最好的传统延续下去。', 'traditions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('traditional-1', 'traditional', 'Traditional skills may disappear unless young people are willing to learn them.', '除非年轻人愿意学习,否则传统技艺可能消失。', 'Traditional');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('custom-1', 'custom', 'Visitors should learn about local customs before travelling to another country.', '游客去其他国家之前应了解当地习俗。', 'customs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convention-1', 'convention', 'Social conventions about marriage have changed greatly in the last fifty years.', '过去五十年,有关婚姻的社会惯例发生了很大变化。', 'conventions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convention-2', 'convention', 'Teachers from around the world will attend the annual convention in Paris.', '来自世界各地的教师将参加在巴黎举行的年度大会。', 'convention');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('value-1', 'value', 'Parents should teach their children the value of hard work.', '父母应该教导孩子勤奋的价值。', 'value');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('value-2', 'value', 'Modern societies tend to value wealth more than wisdom.', '现代社会往往重视财富胜过智慧。', 'value');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('norm-1', 'norm', 'Living alone has become the norm for older people in many countries.', '在许多国家,老年人独居已成为一种规范。', 'norm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('etiquette-1', 'etiquette', 'Business people should learn the etiquette of the country they are visiting.', '商务人士应该学习所访问国家的礼仪。', 'etiquette');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assimilation-1', 'assimilation', 'The assimilation of immigrants into a new society can take several generations.', '移民融入新社会可能需要几代人的时间。', 'assimilation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('integration-1', 'integration', 'Language classes can help with the integration of new immigrants.', '语言课程有助于新移民融入社会。', 'integration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homogenisation-1', 'homogenisation', 'Some people fear the homogenisation of culture around the world.', '有些人担心全球文化趋于同质化。', 'homogenisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('westernisation-1', 'westernisation', 'The westernisation of diets has led to more cases of obesity in Asia.', '饮食西化导致亚洲的肥胖病例增多。', 'westernisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultural-exchange-1', 'cultural-exchange', 'Cultural exchange programmes allow students to experience life in another country.', '文化交流项目让学生能体验另一个国家的生活。', 'Cultural exchange');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mutual-understanding-1', 'mutual-understanding', 'International student exchanges can promote mutual understanding between young people.', '国际学生交流可以促进年轻人之间的相互理解。', 'mutual understanding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stereotype-1', 'stereotype', 'Television often reinforces the stereotype of older people as weak and helpless.', '电视常常强化老年人虚弱无助的刻板印象。', 'stereotype');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prejudice-1', 'prejudice', 'Education is one of the best ways to fight prejudice against other groups.', '教育是消除对其他群体偏见的最好方法之一。', 'prejudice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discrimination-1', 'discrimination', 'Laws against discrimination have improved opportunities for women at work.', '反歧视法律改善了女性的工作机会。', 'discrimination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('racism-1', 'racism', 'Schools have an important role to play in the fight against racism.', '学校在反对种族主义的斗争中发挥着重要作用。', 'racism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tolerance-1', 'tolerance', 'Travel can encourage tolerance of people from different backgrounds.', '旅行可以促进对不同背景的人的宽容。', 'tolerance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ethnic-1', 'ethnic', 'People from different ethnic backgrounds should have equal rights at work.', '不同民族背景的人在工作中应享有平等权利。', 'ethnic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minority-group-1', 'minority-group', 'Every minority group should have the right to use its own language.', '每个少数群体都应有权使用自己的语言。', 'minority group');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immigrant-1', 'immigrant', 'Each immigrant brings new skills and ideas to the receiving country.', '每位移民都为接收国带来新的技能和想法。', 'immigrant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emigrate-1', 'emigrate', 'Many skilled workers emigrate to wealthier countries in search of higher pay.', '许多技术工人移居到较富裕的国家,寻求更高的薪水。', 'emigrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('migrant-worker-1', 'migrant-worker', 'A migrant worker may send most of their income back home.', '外来务工人员可能把大部分收入寄回家。', 'migrant worker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('free-trade-1', 'free-trade', 'Supporters of free trade argue that it creates wealth for all countries.', '自由贸易的支持者认为它为所有国家创造财富。', 'free trade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interdependence-1', 'interdependence', 'Modern trade has led to greater interdependence between nations.', '现代贸易使国家之间更加相互依赖。', 'interdependence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('folk-1', 'folk', 'Young people should be encouraged to learn the folk songs of their region.', '应该鼓励年轻人学习本地区的民间歌曲。', 'folk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('folk-festival-1', 'folk-festival', 'The annual folk festival brings local musicians and visitors together.', '一年一度的民间节日把当地音乐人和游客聚集在一起。', 'folk festival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handicraft-1', 'handicraft', 'Tourism can support local people who make and sell traditional handicrafts.', '旅游业能帮助制作和销售传统手工艺品的当地人。', 'handicrafts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('craftsmanship-1', 'craftsmanship', 'Machine-made goods rarely show the same craftsmanship as those made by hand.', '机器制造的商品很少能展现手工制品的手艺。', 'craftsmanship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artisan-1', 'artisan', 'A local artisan can spend many weeks making a single wooden chair.', '当地的工匠可能花几周时间制作一把木椅。', 'artisan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('art-gallery-1', 'art-gallery', 'Entry to the national art gallery should be free for all children.', '所有儿童都应免费进入国家美术馆。', 'art gallery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhibit-1', 'exhibit', 'Visitors enjoy museums more when they are allowed to touch an exhibit.', '如果可以触摸展品,参观者会更喜欢博物馆。', 'exhibit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhibit-2', 'exhibit', 'The national museum will exhibit these works of art for the first time.', '国家博物馆将首次展出这些艺术品。', 'exhibit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('masterpiece-1', 'masterpiece', 'Every child should have the chance to see a great masterpiece in person.', '每个孩子都应该有机会亲眼看到伟大的杰作。', 'masterpiece');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sculpture-1', 'sculpture', 'Public art, such as a sculpture in a park, can improve a city''s image.', '公园里的雕塑等公共艺术能提升城市形象。', 'sculpture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('literature-1', 'literature', 'Studying literature helps young people to understand different points of view.', '学习文学有助于年轻人理解不同的观点。', 'literature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fiction-1', 'fiction', 'Reading fiction may help children to understand the feelings of others.', '读小说可能有助于孩子理解他人的感受。', 'fiction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('poetry-1', 'poetry', 'Children today read far less poetry than previous generations did.', '如今的孩子读的诗歌比前几代人少得多。', 'poetry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drama-1', 'drama', 'Drama classes can give shy children greater confidence in speaking.', '戏剧课能让害羞的孩子说话更有自信。', 'Drama');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultural-heritage-1', 'cultural-heritage', 'Governments should spend money on protecting the nation''s cultural heritage.', '政府应该投入资金保护国家的文化遗产。', 'cultural heritage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intangible-1', 'intangible', 'Intangible benefits of the arts are often difficult to measure in money.', '艺术无形的益处往往很难用金钱衡量。', 'Intangible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emigrant-1', 'emigrant', 'An emigrant may find it hard to leave family and friends behind.', '移民可能很难离开家人和朋友。', 'emigrant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immigrate-1', 'immigrate', 'Thousands of young professionals immigrate to the country each year.', '每年有数千名年轻专业人士移入这个国家。', 'immigrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aesthetic-1', 'aesthetic', 'New buildings should be judged on aesthetic grounds as well as on cost.', '评价新建筑既要看成本,也要看审美。', 'aesthetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artistic-1', 'artistic', 'Schools should encourage artistic ability as much as academic success.', '学校应该像鼓励学业成功一样鼓励艺术才能。', 'artistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inspiration-1', 'inspiration', 'Nature has long been a source of inspiration for artists and writers.', '大自然一直是艺术家和作家的灵感来源。', 'inspiration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portrait-1', 'portrait', 'A portrait of the queen hangs in the main hall of the museum.', '博物馆大厅里挂着一幅女王的肖像。', 'portrait');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portray-1', 'portray', 'Television programmes often portray older people in a negative way.', '电视节目常常以负面的方式描绘老年人。', 'portray');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impressionism-1', 'impressionism', 'Impressionism changed the way that painters thought about light and colour.', '印象派改变了画家对光和色彩的看法。', 'Impressionism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('watercolour-1', 'watercolour', 'Each watercolour in the exhibition shows a different view of the river.', '展览中的每幅水彩画都展现了河流的不同景色。', 'watercolour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('canvas-1', 'canvas', 'The artist painted the huge canvas for a public building in the capital.', '这位艺术家为首都的一座公共建筑绘制了这幅巨大的画布作品。', 'canvas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('palette-1', 'palette', 'The painter used a limited palette of blues and greys.', '这位画家使用了以蓝色和灰色为主的有限调色板。', 'palette');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pigment-1', 'pigment', 'Early painters made pigment from coloured rocks and plants.', '早期的画家用彩色岩石和植物制作颜料。', 'pigment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embroidery-1', 'embroidery', 'Traditional embroidery from the region is now sold around the world.', '该地区的传统刺绣现在销往世界各地。', 'embroidery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tragedy-1', 'tragedy', 'Shakespeare''s greatest tragedy is still performed in many languages.', '莎士比亚最伟大的悲剧至今仍以多种语言上演。', 'tragedy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('opera-1', 'opera', 'Tickets for the opera are too expensive for many ordinary people.', '歌剧票对许多普通人来说太贵了。', 'opera');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ballet-1', 'ballet', 'The government should support ballet and other art forms that struggle financially.', '政府应该支持芭蕾舞和其他经济困难的艺术形式。', 'ballet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orchestra-1', 'orchestra', 'The city''s orchestra offers free concerts for local school children.', '这座城市的管弦乐队为当地学童提供免费音乐会。', 'orchestra');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('symphony-1', 'symphony', 'The composer wrote his final symphony when he was almost completely deaf.', '这位作曲家创作最后一部交响乐时几乎完全失聪。', 'symphony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chorus-1', 'chorus', 'The school chorus gave a performance at the local home for older people.', '学校合唱团在当地养老院演出。', 'chorus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('percussion-1', 'percussion', 'Children enjoy playing percussion in school music lessons.', '孩子们喜欢在学校音乐课上演奏打击乐器。', 'percussion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cello-1', 'cello', 'My daughter began learning the cello at the age of six.', '我女儿六岁开始学大提琴。', 'cello');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conservatory-1', 'conservatory', 'She won a place to study piano at the national conservatory.', '她考入国家音乐学院学习钢琴。', 'conservatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultural-diversity-1', 'cultural-diversity', 'Immigration has increased the cultural diversity of many large cities.', '移民增加了许多大城市的文化多样性。', 'cultural diversity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unity-1', 'unity', 'National sporting events can create a strong sense of unity.', '全国性体育赛事能营造强烈的团结感。', 'unity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motif-1', 'motif', 'A common motif in local art is the bird, which represents freedom.', '当地艺术中常见的图案是鸟,它象征自由。', 'motif');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weave-1', 'weave', 'Older women in the village still weave cloth using traditional methods.', '村里年长的妇女仍用传统方法织布。', 'weave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('realism-1', 'realism', 'The film was praised for its realism in showing the life of ordinary people.', '这部电影以现实主义手法展现普通人的生活,因此受到赞扬。', 'realism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artwork-1', 'artwork', 'Public artwork can make a city centre more attractive to visitors.', '公共艺术品能让市中心对游客更有吸引力。', 'artwork');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('repertoire-1', 'repertoire', 'The theatre''s repertoire includes both classic plays and modern works.', '这家剧院的全部节目既有经典戏剧,也有现代作品。', 'repertoire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commemorate-1', 'commemorate', 'A national holiday was created to commemorate the end of the war.', '设立了一个全国性节日来纪念战争结束。', 'commemorate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('funeral-1', 'funeral', 'Funeral customs vary greatly from one culture to another.', '葬礼习俗因文化不同而差异很大。', 'Funeral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tourism-1', 'tourism', 'Tourism creates many jobs but can also damage historic sites.', '旅游业创造了许多就业机会,但也可能破坏历史遗迹。', 'Tourism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tourist-attraction-1', 'tourist-attraction', 'The old castle has become the region''s most popular tourist attraction.', '这座古堡已成为该地区最受欢迎的旅游景点。', 'tourist attraction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mass-tourism-1', 'mass-tourism', 'Mass tourism can destroy the natural beauty that attracts visitors in the first place.', '大众旅游可能破坏最初吸引游客的自然美景。', 'Mass tourism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ecotourism-1', 'ecotourism', 'Ecotourism can provide income for local people while protecting wildlife.', '生态旅游能为当地人提供收入,同时保护野生动物。', 'Ecotourism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hospitality-industry-1', 'hospitality-industry', 'The hospitality industry provides millions of jobs for young people.', '酒店业为年轻人提供了数百万个就业机会。', 'hospitality industry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foreign-exchange-1', 'foreign-exchange', 'Tourism is a major source of foreign exchange for many developing countries.', '旅游业是许多发展中国家外汇的主要来源。', 'foreign exchange');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('local-economy-1', 'local-economy', 'Spending by visitors can give a valuable boost to the local economy.', '游客的消费能大大推动当地经济。', 'local economy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('job-opportunity-1', 'job-opportunity', 'Each new hotel creates a job opportunity for people living nearby.', '每家新酒店都为附近居民创造就业机会。', 'job opportunity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overcrowding-1', 'overcrowding', 'Overcrowding at historic sites spoils the experience for many visitors.', '历史遗迹的过度拥挤破坏了许多游客的体验。', 'Overcrowding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commercialisation-1', 'commercialisation', 'The commercialisation of traditional festivals has reduced their cultural meaning.', '传统节日的商业化削弱了它们的文化意义。', 'commercialisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('authentic-1', 'authentic', 'Tourists often want an authentic experience of local life.', '游客往往希望真正体验当地生活。', 'authentic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('authenticity-1', 'authenticity', 'Performances for tourists can lose their cultural authenticity over time.', '为游客举办的表演可能随着时间推移而失去文化真实性。', 'authenticity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exotic-1', 'exotic', 'Cheap flights have made exotic destinations available to ordinary people.', '廉价航班让普通人也能前往异域目的地。', 'exotic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('broaden-ones-horizons-1', 'broaden-ones-horizons', 'Travelling abroad is an excellent way to broaden one''s horizons.', '出国旅行是开阔眼界的极好方式。', 'broaden one''s horizons');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hospitable-1', 'hospitable', 'People in the region are hospitable and often invite visitors into their homes.', '该地区的人们很好客,经常邀请游客到家里做客。', 'hospitable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('local-residents-1', 'local-residents', 'Tourism should bring real benefits to local residents as well as to companies.', '旅游业应该给当地居民以及公司都带来实际好处。', 'local residents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wear-and-tear-1', 'wear-and-tear', 'Millions of visitors cause wear and tear on these ancient buildings.', '数百万游客造成这些古建筑的损耗。', 'wear and tear');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carrying-capacity-1', 'carrying-capacity', 'The island has already exceeded its carrying capacity for tourists.', '这座岛的游客数量已经超过了它的承载能力。', 'carrying capacity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hospitality-1', 'hospitality', 'Visitors are often surprised by the warm hospitality of local people.', '游客常常对当地人的热情好客感到惊讶。', 'hospitality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nuclear-family-1', 'nuclear-family', 'The nuclear family has replaced larger households in most modern cities.', '在大多数现代城市,核心家庭已取代较大的家庭。', 'nuclear family');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extended-family-1', 'extended-family', 'Children in an extended family often receive care from their grandparents.', '大家庭中的孩子常常得到祖父母的照顾。', 'extended family');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('single-parent-family-1', 'single-parent-family', 'Children from a single-parent family can do just as well at school.', '单亲家庭的孩子在学校同样可以表现得很好。', 'single-parent family');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sibling-1', 'sibling', 'Children without siblings may have fewer chances to learn how to share.', '没有兄弟姐妹的孩子学习分享的机会可能更少。', 'siblings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spouse-1', 'spouse', 'Working abroad can put pressure on the relationship between a person and their spouse.', '在国外工作可能给一个人与配偶的关系带来压力。', 'spouse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relative-1', 'relative', 'Older people are increasingly being looked after by a professional rather than a relative.', '老年人越来越多地由专业人员而不是亲戚照顾。', 'relative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relative-2', 'relative', 'The relative cost of food has fallen over the past fifty years.', '过去五十年,食品的相对成本有所下降。', 'relative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('generation-1', 'generation', 'Each generation tends to criticise the behaviour of the one that follows it.', '每一代人都倾向于批评下一代人的行为。', 'generation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('generation-gap-1', 'generation-gap', 'Rapid technological change has made the generation gap wider than ever.', '快速的技术变革使代沟比以往任何时候都大。', 'generation gap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('upbringing-1', 'upbringing', 'A child''s upbringing has a strong influence on their later behaviour.', '孩子的教养对其日后的行为有很大影响。', 'upbringing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parenting-1', 'parenting', 'Good parenting involves setting clear limits as well as showing love.', '好的育儿既要有爱,也要设定明确的界限。', 'parenting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raise-1', 'raise', 'It is argued that parents should raise children to respect other cultures.', '有人认为,父母在抚养孩子时应教导他们尊重其他文化。', 'raise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raise-2', 'raise', 'The government could raise money for public transport by taxing private cars.', '政府可以通过对私家车征税来为公共交通筹集资金。', 'raise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raise-3', 'raise', 'The report raises serious questions about the safety of the food we eat.', '这份报告对我们所吃食物的安全提出了严肃的问题。', 'raises');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spoil-1', 'spoil', 'Parents who give their children too many toys may spoil them.', '给孩子太多玩具的父母可能会把他们宠坏。', 'spoil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spoil-2', 'spoil', 'Large numbers of tourists can spoil the natural beauty of an area.', '大量游客可能破坏一个地区的自然美景。', 'spoil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pamper-1', 'pamper', 'Parents who pamper their children may make them less independent.', '娇惯孩子的父母可能让孩子变得不那么独立。', 'pamper');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bond-1', 'bond', 'Eating together strengthens the bond between parents and children.', '一起吃饭能加强父母和孩子之间的纽带。', 'bond');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intimacy-1', 'intimacy', 'Technology may reduce the intimacy of family relationships.', '技术可能减少家庭关系的亲密。', 'intimacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harmony-1', 'harmony', 'Respect for elders helps to maintain harmony within the family.', '尊敬长辈有助于维持家庭和谐。', 'harmony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sense-of-belonging-1', 'sense-of-belonging', 'Team sports give young people a strong sense of belonging.', '团队运动给年轻人带来强烈的归属感。', 'sense of belonging');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('domestic-1', 'domestic', 'Domestic tasks should be shared equally between men and women.', '家务应该由男女平等分担。', 'Domestic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('domestic-2', 'domestic', 'The domestic economy has been badly affected by the fall in exports.', '国内经济受到出口下降的严重影响。', 'domestic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('domestic-violence-1', 'domestic-violence', 'Victims of domestic violence need safe places to go and legal support.', '家庭暴力的受害者需要安全的去处和法律支持。', 'domestic violence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('household-1', 'household', 'The average household now produces more waste than ever before.', '现在普通家庭产生的垃圾比以往任何时候都多。', 'household');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('housework-1', 'housework', 'Men today do much more housework than their fathers did.', '如今的男性比他们的父辈做更多家务。', 'housework');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chores-1', 'chores', 'Children should help with household chores from an early age.', '孩子应该从小帮忙做家务。', 'chores');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breadwinner-1', 'breadwinner', 'In many families today, the woman is the main breadwinner.', '如今在许多家庭中,女性是主要的养家糊口的人。', 'breadwinner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dual-income-1', 'dual-income', 'Dual-income families often struggle to find enough time with their children.', '双收入家庭常常很难有足够的时间陪孩子。', 'Dual-income');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('childcare-1', 'childcare', 'The high cost of childcare prevents many mothers from returning to work.', '高昂的托儿费用使许多母亲无法重返工作岗位。', 'childcare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nursery-1', 'nursery', 'Government funding for nursery places would help working parents.', '政府资助托儿所名额将帮助在职父母。', 'nursery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('divorce-1', 'divorce', 'Children of parents who divorce may need extra support at school.', '父母离婚的孩子在学校可能需要额外支持。', 'divorce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cohabit-1', 'cohabit', 'More couples now cohabit for several years before getting married.', '现在越来越多的情侣在结婚前同居几年。', 'cohabit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('birth-rate-1', 'birth-rate', 'A falling birth rate means there will be fewer workers in the future.', '出生率下降意味着未来工人减少。', 'birth rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fertility-rate-1', 'fertility-rate', 'The fertility rate has fallen sharply as more women go to university.', '随着上大学的女性增多,生育率急剧下降。', 'fertility rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('population-growth-1', 'population-growth', 'Rapid population growth puts pressure on food and water supplies.', '人口快速增长给食物和水的供应带来压力。', 'population growth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('community-1', 'community', 'Strong community ties can reduce loneliness among older residents.', '紧密的社区联系能减少老年居民的孤独感。', 'community');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-cohesion-1', 'social-cohesion', 'Shared public spaces can help to improve social cohesion in large cities.', '共享的公共空间有助于增强大城市的社会凝聚力。', 'social cohesion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-mobility-1', 'social-mobility', 'Free higher education can increase social mobility for children from poor families.', '免费高等教育能提高贫困家庭孩子的社会流动性。', 'social mobility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inequality-1', 'inequality', 'Inequality between rich and poor has grown in many developed countries.', '在许多发达国家,贫富之间的不平等加剧了。', 'Inequality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wealth-gap-1', 'wealth-gap', 'Higher taxes on the rich could help to reduce the wealth gap.', '提高对富人的税收有助于缩小贫富差距。', 'wealth gap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underprivileged-1', 'underprivileged', 'Scholarships give underprivileged children the chance to attend good universities.', '奖学金让弱势儿童有机会上好大学。', 'underprivileged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disadvantaged-1', 'disadvantaged', 'Disadvantaged students often need extra help from teachers.', '处于劣势的学生往往需要老师的额外帮助。', 'Disadvantaged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homeless-1', 'homeless', 'The government should do more to help homeless people find housing.', '政府应该做更多的事,帮助无家可归的人找到住房。', 'homeless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('donate-1', 'donate', 'Wealthy people should donate more of their money to charity.', '富人应该把更多的钱捐给慈善机构。', 'donate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('donation-1', 'donation', 'A large donation from a local business paid for the new library.', '当地一家企业的巨额捐款支付了新图书馆的费用。', 'donation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('materialism-1', 'materialism', 'Modern advertising strongly encourages materialism among young people.', '现代广告大大助长了年轻人的物质主义。', 'materialism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consumerism-1', 'consumerism', 'Consumerism encourages people to buy things they do not really need.', '消费主义鼓励人们购买并不真正需要的东西。', 'Consumerism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('individualism-1', 'individualism', 'Western societies tend to place greater value on individualism.', '西方社会往往更重视个人主义。', 'individualism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collectivism-1', 'collectivism', 'In cultures based on collectivism, the needs of the group come first.', '在以集体主义为基础的文化中,群体的需求放在首位。', 'collectivism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lifestyle-1', 'lifestyle', 'A healthy lifestyle can reduce the risk of many serious diseases.', '健康的生活方式可以降低许多严重疾病的风险。', 'lifestyle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('work-life-balance-1', 'work-life-balance', 'Flexible hours can help employees to achieve a better work-life balance.', '弹性工作时间能帮助员工更好地实现工作与生活的平衡。', 'work-life balance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surname-1', 'surname', 'In many countries, a woman no longer takes her husband''s surname.', '在许多国家,女性不再随丈夫的姓。', 'surname');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nickname-1', 'nickname', 'Children may feel hurt if they are given an unkind nickname at school.', '如果在学校被起了难听的绰号,孩子可能会感到受伤。', 'nickname');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('engaged-1', 'engaged', 'Couples often stay engaged for several years to save money for a home.', '情侣常常订婚几年,为买房攒钱。', 'engaged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('widow-1', 'widow', 'An elderly widow may feel very lonely after the death of her husband.', '年迈的寡妇在丈夫去世后可能感到非常孤独。', 'widow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marital-1', 'marital', 'Financial problems are a common cause of marital difficulties.', '财务问题是婚姻困难的常见原因。', 'marital');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attachment-1', 'attachment', 'Young children form a strong attachment to the people who care for them.', '幼儿对照顾他们的人产生强烈的依恋。', 'attachment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affinity-1', 'affinity', 'Young people often feel a natural affinity with new technology.', '年轻人往往对新技术有一种天然的亲近感。', 'affinity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mistreat-1', 'mistreat', 'Care homes that mistreat older people should be closed down immediately.', '虐待老人的护理院应该立即关闭。', 'mistreat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equality-1', 'equality', 'Equality between men and women should begin at home.', '男女平等应该从家庭开始。', 'Equality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('needy-1', 'needy', 'Charities provide food and clothing for needy families in the area.', '慈善机构为该地区的贫困家庭提供食物和衣物。', 'needy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impoverished-1', 'impoverished', 'Aid should be directed towards the most impoverished regions of the world.', '援助应该投向世界上最贫困的地区。', 'impoverished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('starvation-1', 'starvation', 'Millions of people still face starvation because of war and drought.', '由于战争和干旱,数百万人仍然面临饥饿。', 'starvation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decent-1', 'decent', 'Every worker deserves a decent wage and safe working conditions.', '每个工人都应该获得体面的工资和安全的工作条件。', 'decent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shabby-1', 'shabby', 'Many older people live in shabby flats they can barely afford to heat.', '许多老人住在破旧的公寓里,几乎付不起取暖费。', 'shabby');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('materialistic-1', 'materialistic', 'Critics say that modern society has become too materialistic.', '批评者说现代社会变得过于物质主义。', 'materialistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mercenary-1', 'mercenary', 'Some companies have a mercenary attitude towards their customers.', '一些公司对待顾客的态度唯利是图。', 'mercenary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ostentatious-1', 'ostentatious', 'Ostentatious displays of wealth can increase envy among poorer people.', '炫耀财富可能加剧较贫穷人群的嫉妒。', 'Ostentatious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pretentious-1', 'pretentious', 'Some people find modern art pretentious and difficult to understand.', '有些人觉得现代艺术自命不凡,难以理解。', 'pretentious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-welfare-1', 'social-welfare', 'Higher taxes are needed to pay for social welfare programmes.', '需要提高税收来支付社会福利项目。', 'social welfare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fast-paced-1', 'fast-paced', 'The fast-paced life of big cities can cause a great deal of stress.', '大城市快节奏的生活可能造成很大压力。', 'fast-paced');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stiff-competition-1', 'stiff-competition', 'Small shops face stiff competition from large supermarkets and online stores.', '小商店面临大型超市和网店的激烈竞争。', 'stiff competition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disability-1', 'disability', 'People with a disability should have equal access to public buildings.', '残疾人应该能平等地使用公共建筑。', 'disability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elite-1', 'elite', 'Expensive private schools help to keep power in the hands of an elite.', '昂贵的私立学校有助于把权力保持在精英手中。', 'elite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('donor-1', 'donor', 'An anonymous donor gave a large sum of money to the hospital.', '一位匿名捐赠者向医院捐赠了一大笔钱。', 'donor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('socially-1', 'socially', 'Children who spend too much time online may become socially isolated.', '上网时间过长的孩子可能在社交上变得孤立。', 'socially');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mobility-1', 'mobility', 'Regular exercise helps older people to maintain their mobility.', '经常锻炼有助于老年人保持行动能力。', 'mobility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sexuality-1', 'sexuality', 'Attitudes towards sexuality have changed considerably over the last fifty years.', '过去五十年,人们对性取向的态度发生了很大变化。', 'sexuality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maternal-1', 'maternal', 'Maternal health has improved greatly in many developing countries.', '在许多发展中国家,母亲的健康状况大大改善。', 'Maternal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gender-1', 'gender', 'Jobs should be given according to ability, regardless of gender.', '工作应该根据能力分配,不分性别。', 'gender');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elderly-1', 'elderly', 'Elderly people have a great deal of knowledge to pass on to the young.', '年长的人有大量知识可以传给年轻人。', 'Elderly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('youngster-1', 'youngster', 'A youngster with a good role model is less likely to get into trouble.', '有好榜样的年轻人不太可能惹上麻烦。', 'youngster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guardian-1', 'guardian', 'Each child''s parent or guardian must sign the form before the trip.', '旅行前,每个孩子的父母或监护人都必须在表格上签字。', 'guardian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abortion-1', 'abortion', 'Laws on abortion differ greatly from one country to another.', '关于堕胎的法律在不同国家差异很大。', 'abortion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ageing-population-1', 'ageing-population', 'An ageing population will increase the demand for health care.', '人口老龄化将增加对医疗保健的需求。', 'ageing population');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('the-elderly-1', 'the-elderly', 'The elderly should be respected for their experience and knowledge.', '老年人的经验和知识应该得到尊重。', 'The elderly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('senior-citizen-1', 'senior-citizen', 'Every senior citizen should have free access to public transport.', '每位老年人都应该可以免费乘坐公共交通。', 'senior citizen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pensioner-1', 'pensioner', 'Many pensioners struggle to pay for heating during the winter.', '许多领养老金的人在冬天难以负担取暖费。', 'pensioners');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retirement-1', 'retirement', 'Many people find it difficult to adapt to life after retirement.', '许多人觉得很难适应退休后的生活。', 'retirement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retirement-age-1', 'retirement-age', 'Many governments are raising the retirement age because people live longer.', '由于人们寿命延长,许多国家的政府正在提高退休年龄。', 'retirement age');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nursing-home-1', 'nursing-home', 'Some older people feel lonely after moving into a nursing home.', '一些老人搬进养老院后感到孤独。', 'nursing home');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('care-home-1', 'care-home', 'Staff in a care home should receive proper training and fair pay.', '护理院的员工应该接受适当的培训并获得公平的薪水。', 'care home');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('caregiver-1', 'caregiver', 'A family caregiver often needs support as well as the person being looked after.', '家庭照料者往往和被照顾者一样需要支持。', 'caregiver');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('empty-nester-1', 'empty-nester', 'An empty-nester may have more time to travel and take up new hobbies.', '空巢老人可能有更多时间旅行和培养新爱好。', 'empty-nester');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lonely-1', 'lonely', 'Many elderly people feel lonely because their children live far away.', '许多老人感到孤独,因为他们的孩子住得很远。', 'lonely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vulnerable-1', 'vulnerable', 'Governments have a special duty to protect the most vulnerable people in society.', '政府有特别的责任保护社会中最脆弱的人。', 'vulnerable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frail-1', 'frail', 'Frail older people may need help with simple daily tasks.', '虚弱的老人可能需要帮忙完成简单的日常事务。', 'Frail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dependent-1', 'dependent', 'More elderly people are becoming dependent on their children for support.', '越来越多的老年人依赖子女的支持。', 'dependent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burden-1', 'burden', 'An ageing population may become a heavy burden on younger taxpayers.', '人口老龄化可能成为年轻纳税人的沉重负担。', 'burden');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pension-scheme-1', 'pension-scheme', 'Companies should offer every worker a good pension scheme.', '公司应该为每位员工提供良好的养老金计划。', 'pension scheme');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workforce-shortage-1', 'workforce-shortage', 'A workforce shortage could slow economic growth in countries with fewer young people.', '在年轻人较少的国家,劳动力短缺可能减缓经济增长。', 'workforce shortage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('filial-piety-1', 'filial-piety', 'Filial piety remains an important value in many Asian societies.', '孝道仍然是许多亚洲社会的重要价值观。', 'Filial piety');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wisdom-1', 'wisdom', 'Older people can pass on their wisdom to younger members of society.', '老年人可以把智慧传给社会的年轻成员。', 'wisdom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physical-exercise-1', 'physical-exercise', 'Regular physical exercise can reduce the risk of many serious diseases.', '经常进行体育锻炼可以降低许多严重疾病的风险。', 'physical exercise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balanced-diet-1', 'balanced-diet', 'Schools should teach children the importance of a balanced diet.', '学校应该教导孩子均衡饮食的重要性。', 'balanced diet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('junk-food-1', 'junk-food', 'Advertising of junk food to children should be banned on television.', '应该禁止在电视上向儿童宣传垃圾食品。', 'junk food');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fast-food-1', 'fast-food', 'The growth of fast food has contributed to rising levels of obesity.', '快餐的发展导致肥胖率上升。', 'fast food');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('processed-food-1', 'processed-food', 'A diet high in processed food can lead to serious health problems.', '大量食用加工食品可能导致严重的健康问题。', 'processed food');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('additive-1', 'additive', 'Food labels should list every additive used in the product.', '食品标签应该列出产品中使用的每种添加剂。', 'additive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preservative-1', 'preservative', 'Some people avoid any food containing a chemical preservative.', '有些人避免吃含有化学防腐剂的任何食品。', 'preservative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('food-safety-1', 'food-safety', 'Stricter laws are needed to improve food safety in restaurants.', '需要更严格的法律来改善餐馆的食品安全。', 'food safety');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overweight-1', 'overweight', 'Overweight children are more likely to have health problems as adults.', '超重儿童成年后更容易出现健康问题。', 'Overweight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mental-health-1', 'mental-health', 'Too much time on social media may damage the mental health of teenagers.', '花太多时间在社交媒体上可能损害青少年的心理健康。', 'mental health');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physical-health-1', 'physical-health', 'Regular walking benefits both physical health and general well-being.', '经常散步对身体健康和整体幸福都有好处。', 'physical health');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('health-insurance-1', 'health-insurance', 'Employers should provide health insurance for all full-time workers.', '雇主应该为所有全职员工提供健康保险。', 'health insurance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preventive-1', 'preventive', 'Preventive medicine is cheaper than treating diseases at a later stage.', '预防性医疗比在后期治疗疾病更便宜。', 'Preventive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-health-1', 'public-health', 'Improving public health should be a priority for every government.', '改善公共卫生应该是每个政府的优先事项。', 'public health');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excluded-1', 'excluded', 'Older people may feel excluded from a society that relies on the internet.', '在依赖互联网的社会中,老年人可能感到被排斥。', 'excluded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outmoded-1', 'outmoded', 'Some people believe that the idea of arranged marriage is outmoded.', '有些人认为包办婚姻的观念已经过时了。', 'outmoded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depressed-1', 'depressed', 'People who feel lonely are more likely to become depressed.', '感到孤独的人更容易变得抑郁。', 'depressed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stressful-1', 'stressful', 'Living in a large city can be noisy and stressful.', '住在大城市可能既吵闹又有压力。', 'stressful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retirement-home-1', 'retirement-home', 'Moving to a retirement home can be a difficult decision for older people.', '搬进养老院对老年人来说可能是个艰难的决定。', 'retirement home');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suicide-1', 'suicide', 'Mental health services can help to reduce the risk of suicide among teenagers.', '心理健康服务有助于降低青少年的自杀风险。', 'suicide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('smoker-1', 'smoker', 'A smoker is far more likely to develop lung cancer than other people.', '吸烟者患肺癌的可能性远高于其他人。', 'smoker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('career-1', 'career', 'Young people should think carefully about their career before choosing a degree.', '年轻人在选择学位前应该仔细考虑职业生涯。', 'career');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('occupation-1', 'occupation', 'People in this occupation often have to work long hours at night.', '从事这种职业的人常常要夜间长时间工作。', 'occupation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('profession-1', 'profession', 'Teaching is a profession that requires both knowledge and patience.', '教学是一种既需要知识又需要耐心的职业。', 'profession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('professional-1', 'professional', 'Professional training should be available to workers throughout their lives.', '工人应该终身都能接受专业培训。', 'Professional');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('professional-2', 'professional', 'Health professionals have warned about the dangers of too much sugar.', '医疗专业人士警告过量摄入糖的危害。', 'professionals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('employment-1', 'employment', 'Automation could reduce employment in many traditional industries.', '自动化可能减少许多传统行业的就业。', 'employment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('job-market-1', 'job-market', 'Graduates need practical skills to compete in today''s job market.', '毕业生需要实用技能才能在当今的就业市场竞争。', 'job market');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('job-security-1', 'job-security', 'Many young workers today have little job security or regular income.', '如今许多年轻工人几乎没有工作保障或固定收入。', 'job security');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('job-satisfaction-1', 'job-satisfaction', 'Job satisfaction is often more important than a high salary.', '工作满意度往往比高薪更重要。', 'Job satisfaction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('career-prospects-1', 'career-prospects', 'Learning a foreign language can greatly improve your career prospects.', '学习外语能大大改善你的职业前景。', 'career prospects');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('promotion-prospects-1', 'promotion-prospects', 'Women often have worse promotion prospects than men in the same jobs.', '女性的晋升机会常常比同岗位的男性差。', 'promotion prospects');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('white-collar-1', 'white-collar', 'White-collar workers usually spend most of their day sitting at a desk.', '白领工人一天大部分时间通常都坐在办公桌前。', 'White-collar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blue-collar-1', 'blue-collar', 'Blue-collar jobs in factories have declined in many developed countries.', '在许多发达国家,工厂里的蓝领工作减少了。', 'Blue-collar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manual-labour-1', 'manual-labour', 'Machines have replaced much of the manual labour once done in factories.', '机器已经取代了工厂里过去的许多体力劳动。', 'manual labour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skilled-1', 'skilled', 'There is a serious shortage of skilled workers in the building trade.', '建筑行业严重缺乏熟练工人。', 'skilled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unskilled-1', 'unskilled', 'Unskilled workers are the most likely to lose their jobs to machines.', '非熟练工人最有可能因机器而失业。', 'Unskilled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expertise-1', 'expertise', 'The company lacks the technical expertise to develop this new product.', '这家公司缺乏开发这种新产品的专业知识。', 'expertise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workload-1', 'workload', 'Teachers complain that their heavy workload leaves little time for their families.', '老师们抱怨繁重的工作量让他们几乎没有时间陪家人。', 'workload');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burnout-1', 'burnout', 'Long hours and constant pressure can lead to burnout among nurses.', '长时间工作和持续的压力可能导致护士职业倦怠。', 'burnout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workaholic-1', 'workaholic', 'A workaholic may damage both their health and their family life.', '工作狂可能既损害健康,也损害家庭生活。', 'workaholic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remote-working-1', 'remote-working', 'Remote working saves time and reduces traffic during the rush hour.', '远程办公节省时间,还能减少高峰期的交通流量。', 'Remote working');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freelance-1', 'freelance', 'Freelance work offers flexibility but no guarantee of a regular income.', '自由职业提供灵活性,但不能保证有固定收入。', 'Freelance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('self-employed-1', 'self-employed', 'Self-employed workers enjoy more freedom but often have less financial security.', '个体经营者享有更多自由,但经济保障往往较少。', 'Self-employed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gig-economy-1', 'gig-economy', 'Workers in the gig economy often have no sick pay or holiday pay.', '零工经济中的工人常常没有病假工资或假期工资。', 'gig economy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minimum-wage-1', 'minimum-wage', 'Raising the minimum wage could help the lowest-paid workers in society.', '提高最低工资可以帮助社会上收入最低的工人。', 'minimum wage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('earnings-1', 'earnings', 'Average earnings have not kept up with rising house prices.', '平均收入没有跟上房价上涨的速度。', 'earnings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fringe-benefits-1', 'fringe-benefits', 'Fringe benefits, such as free meals, can help companies to attract staff.', '免费餐食等附加福利能帮助公司吸引员工。', 'Fringe benefits');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gender-gap-1', 'gender-gap', 'The gender gap in pay remains large in many industries.', '在许多行业,薪酬方面的性别差距仍然很大。', 'gender gap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gender-equality-1', 'gender-equality', 'Gender equality at work benefits both employers and the wider economy.', '工作中的性别平等对雇主和整体经济都有益。', 'Gender equality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gender-discrimination-1', 'gender-discrimination', 'Gender discrimination remains a serious barrier to women''s progress in some jobs.', '在某些工作中,性别歧视仍是女性发展的严重障碍。', 'Gender discrimination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('glass-ceiling-1', 'glass-ceiling', 'The glass ceiling still prevents many women from reaching top jobs.', '玻璃天花板仍然阻碍许多女性获得高层职位。', 'glass ceiling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feminism-1', 'feminism', 'Feminism has helped women to gain greater rights at home and at work.', '女权主义帮助女性在家庭和工作中获得了更多权利。', 'Feminism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equal-pay-1', 'equal-pay', 'Men and women should receive equal pay for doing the same job.', '男女做同样的工作应该同工同酬。', 'equal pay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paternity-leave-1', 'paternity-leave', 'Longer paternity leave would allow fathers to spend more time with their babies.', '更长的陪产假能让父亲有更多时间陪伴婴儿。', 'paternity leave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lay-off-1', 'lay-off', 'Falling sales forced the company to lay off a third of its workers.', '销量下滑迫使公司裁掉三分之一的员工。', 'lay off');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('redundancy-1', 'redundancy', 'Workers facing redundancy need help to find new types of employment.', '面临裁员的工人需要帮助,以找到新类型的工作。', 'redundancy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dismiss-1', 'dismiss', 'Employers should not be able to dismiss workers without a good reason.', '雇主不应在没有充分理由的情况下解雇员工。', 'dismiss');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dismiss-2', 'dismiss', 'It would be wrong to dismiss these concerns as unimportant.', '把这些担忧视为不重要是错误的。', 'dismiss');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unemployed-1', 'unemployed', 'Unemployed young people should receive training to help them find work.', '失业的年轻人应该接受培训,帮助他们找到工作。', 'Unemployed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jobseeker-1', 'jobseeker', 'Each jobseeker should receive advice on how to write a good CV.', '每位求职者都应该得到关于如何写好简历的建议。', 'jobseeker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('labour-market-1', 'labour-market', 'Older workers may find it hard to compete in the modern labour market.', '年长的工人可能很难在现代劳动力市场上竞争。', 'labour market');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arduous-1', 'arduous', 'Mining remains an arduous and dangerous job in many parts of the world.', '在世界许多地方,采矿仍是一项艰巨而危险的工作。', 'arduous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('repetitive-1', 'repetitive', 'Robots are well suited to repetitive tasks that humans find boring.', '机器人非常适合人类觉得无聊的重复性工作。', 'repetitive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freelancer-1', 'freelancer', 'A freelancer may have to work evenings and weekends to earn enough.', '自由职业者可能要在晚上和周末工作才能赚够钱。', 'freelancer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('programmer-1', 'programmer', 'A good programmer can find well-paid work almost anywhere in the world.', '优秀的程序员几乎可以在世界任何地方找到高薪工作。', 'programmer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('translator-1', 'translator', 'Software may eventually replace the work of a human translator.', '软件最终可能取代人工译者的工作。', 'translator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detective-1', 'detective', 'The detective spent months collecting evidence against the company.', '这名侦探花了几个月时间收集对这家公司不利的证据。', 'detective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chef-1', 'chef', 'A chef often has to work long hours in hot and crowded conditions.', '厨师常常要在炎热拥挤的环境中长时间工作。', 'chef');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tailor-1', 'tailor', 'The number of people who train as a tailor has fallen sharply.', '接受裁缝培训的人数急剧下降。', 'tailor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('florist-1', 'florist', 'A local florist may struggle to compete with cheap supermarket flowers.', '当地的花商可能很难与超市的廉价鲜花竞争。', 'florist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('butcher-1', 'butcher', 'The local butcher closed when a large supermarket opened nearby.', '附近开了一家大超市后,当地的肉贩关了店。', 'butcher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('greengrocer-1', 'greengrocer', 'Fewer people buy their vegetables from a greengrocer these days.', '如今从蔬果商那里买菜的人越来越少了。', 'greengrocer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decorator-1', 'decorator', 'We hired a decorator to paint the walls of the new office.', '我们雇了一名室内装修工来粉刷新办公室的墙。', 'decorator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('novelist-1', 'novelist', 'A successful novelist may spend years writing a single book.', '成功的小说家可能花费数年时间写一本书。', 'novelist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('composer-1', 'composer', 'The composer''s music is still played regularly by orchestras around the world.', '这位作曲家的音乐至今仍被世界各地的管弦乐队经常演奏。', 'composer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('philosopher-1', 'philosopher', 'The Greek philosopher argued that education should develop good citizens.', '这位希腊哲学家认为,教育应该培养好公民。', 'philosopher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physicist-1', 'physicist', 'The young physicist won an international prize for her work on light.', '这位年轻的物理学家因光学研究获得了一项国际奖项。', 'physicist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('geologist-1', 'geologist', 'A geologist studies rocks to understand the history of the Earth.', '地质学家研究岩石以了解地球的历史。', 'geologist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mathematician-1', 'mathematician', 'Every mathematician knows how difficult this ancient problem has been.', '每位数学家都知道这个古老的问题有多难。', 'mathematician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biologist-1', 'biologist', 'A marine biologist studies the plants and animals that live in the sea.', '海洋生物学家研究生活在海中的动植物。', 'biologist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prestige-1', 'prestige', 'Many people choose medicine because of the prestige of the profession.', '许多人选择学医是因为这个职业的声望。', 'prestige');
